entry.content:
C++面对对象笔记整理： 内存分区：C++程序在执行时，将内存大方向划分为4个区域
代码区：存放函数体的二进制代码，由操作系统进行管理的 全局区：存放全局变量和静态变量以及常量 栈区：由编译器自动分配释放, 存放函数的参数值,局部变量等 堆区：由程序员分配和释放,若程序员不释放,程序结束时由操作系统回收
内存四区意义： 不同区域存放的数据，赋予不同的生命周期, 给我们更大的灵活编程 ​ 代码区：
存放 CPU 执行的机器指令
代码区是共享的，共享的目的是对于频繁被执行的程序，只需要在内存中有一份代码即可
代码区是只读的，使其只读的原因是防止程序意外地修改了它的指令
​ 全局区：
全局变量和静态变量存放在此.
全局区还包含了常量区, 字符串常量和其他常量也存放在此.
该区域的数据在程序结束后由操作系统释放
程序运行前示例： //全局变量int g_a = 10;int g_b = 10;//全局常量const int c_g_a = 10;const int c_g_b = 10;int main() &#123; //局部变量 int a = 10; int b = 10; //打印地址 cout &lt;&lt; &quot;局部变量a地址为： &quot; &lt;&lt; (int)&amp;a &lt;&lt; endl; cout &lt;&lt; &quot;局部变量b地址为： &quot; &lt;&lt; (int)&amp;b &lt;&lt; endl; cout &lt;&lt; &quot;全局变量g_a地址为： &quot; &lt;&lt; (int)&amp;g_a &lt;&lt; endl; cout &lt;&lt; &quot;全局变量g_b地址为： &quot; &lt;&lt; (int)&amp;g_b &lt;&lt; endl; //静态变量 static int s_a = 10; static int s_b = 10; cout &lt;&lt; &quot;静态变量s_a地址为： &quot; &lt;&lt; (int)&amp;s_a &lt;&lt; endl; cout &lt;&lt; &quot;静态变量s_b地址为： &quot; &lt;&lt; (int)&amp;s_b &lt;&lt; endl; cout &lt;&lt; &quot;字符串常量地址为： &quot; &lt;&lt; (int)&amp;&quot;hello world&quot; &lt;&lt; endl; cout &lt;&lt; &quot;字符串常量地址为： &quot; &lt;&lt; (int)&amp;&quot;hello world1&quot; &lt;&lt; endl; cout &lt;&lt; &quot;全局常量c_g_a地址为： &quot; &lt;&lt; (int)&amp;c_g_a &lt;&lt; endl; cout &lt;&lt; &quot;全局常量c_g_b地址为： &quot; &lt;&lt; (int)&amp;c_g_b &lt;&lt; endl; const int c_l_a = 10; const int c_l_b = 10; cout &lt;&lt; &quot;局部常量c_l_a地址为： &quot; &lt;&lt; (int)&amp;c_l_a &lt;&lt; endl; cout &lt;&lt; &quot;局部常量c_l_b地址为： &quot; &lt;&lt; (int)&amp;c_l_b &lt;&lt; endl; system(&quot;pause&quot;); return 0;&#125;
总结：
C++中在程序运行前分为全局区和代码区 代码区特点是共享和只读 全局区中存放全局变量、静态变量、常量 常量区中存放 const修饰的全局常量 和 字符串常量 全局变量、静态变量、全局常量的地址&amp;隔得比较近
程序运行后​ 栈区： ​ 由编译器自动分配释放, 存放函数的参数值,局部变量等 示例： int * func()&#123; int a = 10; return &amp;a;&#125;int main() &#123; int *p = func(); cout &lt;&lt; *p &lt;&lt; endl; cout &lt;&lt; *p &lt;&lt; endl; system(&quot;pause&quot;); return 0;&#125;
总结：栈区由编译器自动分配释放, 存放函数的参数值,局部变量等 ​ 堆区： ​ 由程序员分配释放,若程序员不释放,程序结束时由操作系统回收 ​ 在C++中主要利用new在堆区开辟内存 示例： int* func()&#123; int* a = new int(10); return a;&#125;int main() &#123; int *p = func(); cout &lt;&lt; *p &lt;&lt; endl; cout &lt;&lt; *p &lt;&lt; endl; system(&quot;pause&quot;); return 0;&#125;
总结：
堆区数据由程序员管理开辟和释放
堆区数据利用new关键字进行开辟内存
new操作符​ C++中利用new操作符在堆区开辟数据 ​ 堆区开辟的数据，由程序员手动开辟，手动释放，释放利用操作符 delete ​ 语法： new 数据类型 ​ 利用new创建的数据，会返回该数据对应的类型的指针 示例1： 基本语法 int* func()&#123; int* a = new int(10); return a;&#125;int main() &#123; int *p = func(); cout &lt;&lt; *p &lt;&lt; endl; cout &lt;&lt; *p &lt;&lt; endl; //利用delete释放堆区数据 delete p; //cout &lt;&lt; *p &lt;&lt; endl; //报错，释放的空间不可访问 system(&quot;pause&quot;); return 0;&#125;
示例2：开辟数组 //堆区开辟数组int main() &#123; int* arr = new int[10]; for (int i = 0; i &lt; 10; i++) &#123; arr[i] = i + 100; &#125; for (int i = 0; i &lt; 10; i++) &#123; cout &lt;&lt; arr[i] &lt;&lt; endl; &#125; //释放数组 delete 后加 [] delete[] arr; system(&quot;pause&quot;); return 0;&#125;
引用引用的基本使用**作用： **给变量起别名 语法： 数据类型 &amp;别名 = 原名 示例： int main() &#123; int a = 10; int &amp;b = a; cout &lt;&lt; &quot;a = &quot; &lt;&lt; a &lt;&lt; endl; cout &lt;&lt; &quot;b = &quot; &lt;&lt; b &lt;&lt; endl; b = 100; cout &lt;&lt; &quot;a = &quot; &lt;&lt; a &lt;&lt; endl; cout &lt;&lt; &quot;b = &quot; &lt;&lt; b &lt;&lt; endl; system(&quot;pause&quot;); return 0;&#125;
引用注意事项 引用必须初始化 引用在初始化后，不可以改变
示例： int main() &#123; int a = 10; int b = 20; //int &amp;c; //错误，引用必须初始化 int &amp;c = a; //一旦初始化后，就不可以更改 c = b; //这是赋值操作，不是更改引用 cout &lt;&lt; &quot;a = &quot; &lt;&lt; a &lt;&lt; endl; cout &lt;&lt; &quot;b = &quot; &lt;&lt; b &lt;&lt; endl; cout &lt;&lt; &quot;c = &quot; &lt;&lt; c &lt;&lt; endl; system(&quot;pause&quot;); return 0;&#125;
引用做函数参数作用：函数传参时，可以利用引用的技术让形参修饰实参 优点：可以简化指针修改实参 示例： //1. 值传递，把主函数里面的a,b的值传过来，把主函数里面的实参a,b的值赋给了形参a,b,在mySwap01函数里面的形参a,b的值发生了改变，但是主函数的里面的a,b的地址和值都没有改变void mySwap01(int a, int b) &#123; int temp = a; a = b; b = temp;&#125;//2. 地址传递,通过把主函数里面的a,b的地址和值传给 mySwap02的*a,*b。即a的地址原来是01，值为10，b的地址是02，值是20，在mySwap02中的通过*a和*b传过来主函数的a,b的地址和值，将a的地址和值转换成02,20,b的地址和值转换成01,10void mySwap02(int* a, int* b) &#123; int temp = *a; *a = *b; *b = temp;&#125;//3. 引用传递，在mySwap03中&amp;a,&amp;b指向主函数的a,b对应地址。比如原先的a,b的地址分别为01,02，进行交换之后,a,b的地址没有变，但是把01,02地址的里面的值交换了，即变量a的地址为01的值变成了20,变量b的地址为02的值变成了10void mySwap03(int&amp; a, int&amp; b) &#123; int temp = a; a = b; b = temp;&#125;int main() &#123; int a = 10; int b = 20; mySwap01(a, b); cout &lt;&lt; &quot;a:&quot; &lt;&lt; a &lt;&lt; &quot; b:&quot; &lt;&lt; b &lt;&lt; endl; mySwap02(&amp;a, &amp;b); cout &lt;&lt; &quot;a:&quot; &lt;&lt; a &lt;&lt; &quot; b:&quot; &lt;&lt; b &lt;&lt; endl; mySwap03(a, b); cout &lt;&lt; &quot;a:&quot; &lt;&lt; a &lt;&lt; &quot; b:&quot; &lt;&lt; b &lt;&lt; endl; system(&quot;pause&quot;); return 0;&#125;
总结：通过引用参数产生的效果同按地址传递是一样的。引用的语法更清楚简单
引用做函数返回值作用：引用是可以作为函数的返回值存在的 注意：不要返回局部变量引用 用法：函数调用作为左值 示例： //返回局部变量引用int&amp; test01() &#123; int a = 10; //局部变量，存放在栈区，返回之后会被自动释放 return a;&#125;//返回静态变量引用int&amp; test02() &#123; static int a = 20;//全局变量 return a;&#125;int main() &#123; //不能返回局部变量的引用 int&amp; ref = test01(); cout &lt;&lt; &quot;ref = &quot; &lt;&lt; ref &lt;&lt; endl;//第一次会被编译器保存 cout &lt;&lt; &quot;ref = &quot; &lt;&lt; ref &lt;&lt; endl;//第二次就不会保存,a的内存已经被释放 //如果函数做左值，那么必须返回引用 int&amp; ref2 = test02(); cout &lt;&lt; &quot;ref2 = &quot; &lt;&lt; ref2 &lt;&lt; endl; cout &lt;&lt; &quot;ref2 = &quot; &lt;&lt; ref2 &lt;&lt; endl;//20 test02() = 1000;//把1000赋值给a也就相当于赋给了a的别名ref2 cout &lt;&lt; &quot;ref2 = &quot; &lt;&lt; ref2 &lt;&lt; endl;//1000 cout &lt;&lt; &quot;ref2 = &quot; &lt;&lt; ref2 &lt;&lt; endl; system(&quot;pause&quot;); return 0;&#125;
​ 引用的本质本质：引用的本质在c++内部实现是一个指针常量. 讲解示例： //发现是引用，转换为 int* const ref = &amp;a;void func(int&amp; ref)&#123; ref = 100; // ref是引用，转换为*ref = 100&#125;int main()&#123; int a = 10; //自动转换为 int* const ref = &amp;a; 指针常量是指针指向不可改，也说明为什么引用不可更改 int&amp; ref = a; ref = 20; //内部发现ref是引用，自动帮我们转换为: *ref = 20; cout &lt;&lt; &quot;a:&quot; &lt;&lt; a &lt;&lt; endl; cout &lt;&lt; &quot;ref:&quot; &lt;&lt; ref &lt;&lt; endl; func(a); return 0;&#125;
结论：C++推荐用引用技术，因为语法方便，引用本质是指针常量，但是所有的指针操作编译器都帮我们做了 常量引用作用：常量引用主要用来修饰形参，防止误操作 在函数形参列表中，可以加==const修饰形参==，防止形参改变实参 示例： //引用使用的场景，通常用来修饰形参void showValue(const int&amp; v) &#123; //v += 10; //因为const的存在 v=1000修改不了v cout &lt;&lt; v &lt;&lt; endl;&#125;int main() &#123; //int&amp; ref = 10; 引用本身需要一个合法的内存空间，因此这行错误，10是一个常量 //加入const就可以了，编译器优化代码，相当于int temp = 10; const int&amp; ref = temp; const int&amp; ref = 10; //ref = 100; //加入const后不可以修改变量 cout &lt;&lt; ref &lt;&lt; endl; //函数中利用常量引用防止误操作修改实参 int a = 10; showValue(a); system(&quot;pause&quot;); return 0;&#125;
函数提高函数默认参数在C++中，函数的形参列表中的形参是可以有默认值的。 语法： 返回值类型 函数名 （参数= 默认值）&#123;&#125; 示例： int func(int a, int b = 10, int c = 10) &#123; return a + b + c;&#125;//1. 如果某个位置参数有默认值，那么从这个位置往后，从左向右，必须都要有默认值//2. 如果函数声明有默认值，函数实现的时候就不能有默认参数，即：声明和实现只能有一个默认参数//3、如果我们自己传入数据，就用自己的数据，如果没有就用默认值int func2(int a = 10, int b = 10);//声明函数int func2(int a, int b) &#123;//实现函数 return a + b;&#125;int main() &#123; cout &lt;&lt; &quot;ret = &quot; &lt;&lt; func(20, 20) &lt;&lt; endl; cout &lt;&lt; &quot;ret = &quot; &lt;&lt; func(100) &lt;&lt; endl; cout &lt;&lt; func2(10,10)&lt;&lt;endl; cout &lt;&lt; func2()&lt;&lt;endl; system(&quot;pause&quot;); return 0;&#125;
函数占位参数C++中函数的形参列表里可以有占位参数，用来做占位，调用函数时必须填补该位置 语法： 返回值类型 函数名 (数据类型)&#123;&#125; 在现阶段函数的占位参数存在意义不大，但是后面的课程中会用到该技术 示例： //函数占位参数 ，占位参数也可以有默认参数void func(int a, int) &#123;//void func(int a, int =10) cout &lt;&lt; &quot;this is func&quot; &lt;&lt; endl;&#125;int main() &#123; func(10,10); //占位参数必须填补 system(&quot;pause&quot;); return 0;&#125;
函数重载函数重载概述作用：函数名可以相同，提高复用性 函数重载满足条件：
同一个作用域下 函数名称相同 函数参数类型不同 或者 个数不同 或者 顺序不同
注意: 函数的返回值不可以作为函数重载的条件 示例： //函数重载需要函数都在同一个作用域下void func()&#123; cout &lt;&lt; &quot;func 的调用！&quot; &lt;&lt; endl;&#125;void func(int a)&#123; cout &lt;&lt; &quot;func (int a) 的调用！&quot; &lt;&lt; endl;&#125;void func(double a)&#123; cout &lt;&lt; &quot;func (double a)的调用！&quot; &lt;&lt; endl;&#125;void func(int a ,double b)&#123; cout &lt;&lt; &quot;func (int a ,double b) 的调用！&quot; &lt;&lt; endl;&#125;void func(double a ,int b)&#123; cout &lt;&lt; &quot;func (double a ,int b)的调用！&quot; &lt;&lt; endl;&#125;//修改函数返回值类型不可以作为函数重载条件//int func(double a, int b)//&#123;// cout &lt;&lt; &quot;func (double a ,int b)的调用！&quot; &lt;&lt; endl;//&#125;int main() &#123; func(); func(10); func(3.14); func(10,3.14); func(3.14 , 10); system(&quot;pause&quot;); return 0;&#125;
函数重载注意事项 引用作为重载条件 函数重载碰到函数默认参数
示例： //函数重载注意事项//1、引用作为重载条件void func(int &amp;a)//int &amp;a=10,不合法&#123; cout &lt;&lt; &quot;func (int &amp;a) 调用 &quot; &lt;&lt; endl;&#125;void func(const int &amp;a)&#123; cout &lt;&lt; &quot;func (const int &amp;a) 调用 &quot; &lt;&lt; endl;&#125;//2、函数重载碰到函数默认参数void func2(int a, int b = 10)&#123; cout &lt;&lt; &quot;func2(int a, int b = 10) 调用&quot; &lt;&lt; endl;&#125;void func2(int a)&#123; cout &lt;&lt; &quot;func2(int a) 调用&quot; &lt;&lt; endl;&#125;int main() &#123; int a = 10; func(a); //调用无const，a是一个变量，不是常量 func(10);//调用有const，10是一个常量const //func2(10); //碰到默认参数产生歧义，即：void func2(int a)和void func2(int a, int b = 10)均可以被调用，出现二义性，需要避免，所以写函数重载的时候，尽量避免形参中有默认参数的出现 system(&quot;pause&quot;); return 0;&#125;
类和对象C++面向对象的三大特性为：==封装、继承、多态== C++认为==万事万物都皆为对象==，对象上有其属性和行为 例如： ​ 人可以作为对象，属性有姓名、年龄、身高、体重…，行为有走、跑、跳、吃饭、唱歌… ​ 车也可以作为对象，属性有轮胎、方向盘、车灯…,行为有载人、放音乐、放空调… ​ 具有相同性质的==对象==，我们可以抽象称为==类==，人属于人类，车属于车类 封装封装的意义封装是C++面向对象三大特性之一 封装的意义：
将属性和行为作为一个整体，表现生活中的事物 将属性和行为加以权限控制
封装意义一： ​ 在设计类的时候，属性和行为写在一起，表现事物 语法： class 类名&#123; 访问权限： 属性 / 行为 &#125;; 示例1：设计一个圆类，求圆的周长 示例代码： //圆周率const double PI = 3.14;//1、封装的意义//将属性和行为作为一个整体，用来表现生活中的事物//封装一个圆类，求圆的周长//class代表设计一个类，后面跟着的是类名class Circle&#123;public: //访问权限 公共的权限 //属性 int m_r;//半径 //行为 //获取到圆的周长 double calculateZC() &#123; //2 * pi * r //获取圆的周长 return 2 * PI * m_r; &#125;&#125;;int main() &#123; //通过圆类，创建圆的对象c1 // c1就是一个具体的圆 Circle c1; c1.m_r = 10; //给圆对象的半径 进行赋值操作 //2 * pi * 10 = = 62.8 cout &lt;&lt; &quot;圆的周长为： &quot; &lt;&lt; c1.calculateZC() &lt;&lt; endl; system(&quot;pause&quot;); return 0;&#125;
示例2：设计一个学生类，属性有姓名和学号，可以给姓名和学号赋值，可以显示学生的姓名和学号 示例2代码： //学生类,属性+行为=成员class Student &#123;public://行为 void setName(string name) &#123; m_name = name; &#125; void setID(int id) &#123; m_id = id; &#125; void showStudent() &#123; cout &lt;&lt; &quot;name:&quot; &lt;&lt; m_name &lt;&lt; &quot; ID:&quot; &lt;&lt; m_id &lt;&lt; endl; &#125;public://属性 string m_name; int m_id;&#125;;int main() &#123; Student stu; stu.setName(&quot;德玛西亚&quot;);//stu.m_name=&quot;德玛西亚&quot; stu.setID(250);//stu.id=250 stu.showStudent(); system(&quot;pause&quot;); return 0;&#125;
封装意义二： 类在设计时，可以把属性和行为放在不同的权限下，加以控制 访问权限有三种：
public 公共权限 protected 保护权限 private 私有权限
示例： //三种权限//公共权限 public 类内可以访问 类外可以访问//保护权限 protected 类内可以访问 类外不可以访问 可以通过所属类的成员函数、友元类、友元函数、派生类对象//私有权限 private 类内可以访问 类外不可以访问 只可以被所属类的成员函数、友元函数、友元类class Person&#123; //姓名 公共权限public: string m_Name; //汽车 保护权限protected: string m_Car; //银行卡密码 私有权限private: int m_Password;public: void func() &#123; m_Name = &quot;张三&quot;; m_Car = &quot;拖拉机&quot;; m_Password = 123456; &#125;&#125;;int main() &#123; //实例化对象p Person p; p.m_Name = &quot;李四&quot;; //p.m_Car = &quot;奔驰&quot;; //保护权限类外访问不到 //p.m_Password = 123; //私有权限类外访问不到 p.func(); system(&quot;pause&quot;); return 0;&#125;
struct和class区别在C++中 struct和class唯一的区别就在于 默认的访问权限不同 区别：
struct 默认权限为公共 class 默认权限为私有
class C1&#123; int m_A; //默认是私有权限&#125;;struct C2&#123; int m_A; //默认是公共权限&#125;;int main() &#123; C1 c1; c1.m_A = 10; //错误，访问权限是私有 C2 c2; c2.m_A = 10; //正确，访问权限是公共 system(&quot;pause&quot;); return 0;&#125;
成员属性设置为私有优点1：将所有成员属性设置为私有，可以自己控制读写权限 优点2：对于写权限，我们可以检测数据的有效性 示例： class Person &#123;public: //姓名设置可读可写 void setName(string name) &#123; m_Name = name; &#125; string getName() &#123; return m_Name; &#125; //获取年龄 int getAge() &#123; return m_Age; &#125; //设置年龄 void setAge(int age) &#123; if (age &lt; 0 || age &gt; 150) &#123; cout &lt;&lt; &quot;你个老妖精!&quot; &lt;&lt; endl; return; &#125; m_Age = age; &#125; //情人设置为只写 void setLover(string lover) &#123; m_Lover = lover; &#125;private: string m_Name; //可读可写 姓名 int m_Age; //只读 年龄,如果需要读取，那么就写一个getAge函数 string m_Lover; //只写 情人&#125;;int main() &#123; Person p; //姓名设置 p.setName(&quot;张三&quot;); cout &lt;&lt; &quot;姓名： &quot; &lt;&lt; p.getName() &lt;&lt; endl; //年龄设置 p.setAge(50); cout &lt;&lt; &quot;年龄： &quot; &lt;&lt; p.getAge() &lt;&lt; endl; //情人设置 p.setLover(&quot;苍井&quot;); //cout &lt;&lt; &quot;情人： &quot; &lt;&lt; p.m_Lover &lt;&lt; endl; //只写属性，不可以读取 system(&quot;pause&quot;); return 0;&#125;
对象的初始化和清理 生活中我们买的电子产品都基本会有出厂设置，在某一天我们不用时候也会删除一些自己信息数据保证安全 C++中的面向对象来源于生活，每个对象也都会有初始设置以及 对象销毁前的清理数据的设置。
构造函数和析构函数对象的初始化和清理也是两个非常重要的安全问题 ​ 一个对象或者变量没有初始状态，对其使用后果是未知 ​ 同样的使用完一个对象或变量，没有及时清理，也会造成一定的安全问题 c++利用了构造函数和析构函数解决上述问题，这两个函数将会被编译器自动调用，完成对象初始化和清理工作。 对象的初始化和清理工作是编译器强制要我们做的事情，因此如果我们不提供构造和析构，编译器会提供 编译器提供的构造函数和析构函数是空实现。
构造函数：主要作用在于创建对象时为对象的成员属性赋值，构造函数由编译器自动调用，无须手动调用。 析构函数：主要作用在于对象销毁前系统自动调用，执行一些清理工作。
构造函数语法：类名()&#123;&#125;
构造函数，没有返回值也不写void 函数名称与类名相同 构造函数可以有参数，因此可以发生重载 程序在调用对象时候会自动调用构造，无须手动调用,而且只会调用一次
析构函数语法： ~类名()&#123;&#125;
析构函数，没有返回值也不写void 函数名称与类名相同,在名称前加上符号 ~ 析构函数不可以有参数，因此不可以发生重载 程序在对象销毁前会自动调用析构，无须手动调用,而且只会调用一次
class Person&#123;public: //构造函数 Person() &#123; cout &lt;&lt; &quot;Person的构造函数调用&quot; &lt;&lt; endl; &#125; //析构函数 ~Person() &#123; cout &lt;&lt; &quot;Person的析构函数调用&quot; &lt;&lt; endl; &#125;&#125;; void test01()&#123; Person p;&#125;int main() &#123; test01(); system(&quot;pause&quot;); return 0;&#125;
构造函数的分类及调用两种分类方式： ​ 按参数分为： 有参构造和无参构造 ​ 按类型分为： 普通构造和拷贝构造 三种调用方式： ​ 括号法 ​ 显示法 ​ 隐式转换法 示例： //1、构造函数分类// 按照参数分类分为 有参和无参构造 无参又称为默认构造函数// 按照类型分类分为 普通构造和拷贝构造class Person &#123;public: //无参（默认）构造函数 Person() &#123; cout &lt;&lt; &quot;无参构造函数!&quot; &lt;&lt; endl; &#125; //有参构造函数 Person(int a) &#123; age = a; cout &lt;&lt; &quot;有参构造函数!&quot; &lt;&lt; endl; &#125; //拷贝构造函数 Person(const Person&amp; p) &#123; age = p.age; cout &lt;&lt; &quot;拷贝构造函数!&quot; &lt;&lt; endl; &#125; //析构函数 ~Person() &#123; cout &lt;&lt; &quot;析构函数!&quot; &lt;&lt; endl; &#125;public: int age;&#125;;//2、构造函数的调用//调用无参构造函数void test01() &#123; Person p; //调用无参构造函数&#125;//调用有参的构造函数void test02() &#123; //2.1 括号法，常用 Person p1(10); //注意1：调用无参构造函数不能加括号，如果加了编译器认为这是一个函数声明 //Person p2();类似于void func(); //2.2 显式法 Person p2 = Person(10); //有参构造p2，即：右边的无名函数声明取名为p2 Person p3 = Person(p2);//拷贝构造p3 //Person(10)单独写就是匿名对象 当前行结束之后，马上析构 //2.3 隐式转换法 Person p4 = 10; // Person p4 = Person(10); Person p5 = p4; // Person p5 = Person(p4); //注意2：不能利用 拷贝构造函数 初始化匿名对象 编译器认为是对象声明，即：Person(p3)===Person p3，会默认为重定义 //Person p5(p4);&#125;int main() &#123; test01(); //test02(); system(&quot;pause&quot;); return 0;&#125;
拷贝构造函数调用时机C++中拷贝构造函数调用时机通常有三种情况
使用一个已经创建完毕的对象来初始化一个新对象 值传递的方式给函数参数传值 以值方式返回局部对象
示例： class Person &#123;public: Person() &#123; cout &lt;&lt; &quot;无参构造函数!&quot; &lt;&lt; endl; mAge = 0; &#125; Person(int age) &#123; cout &lt;&lt; &quot;有参构造函数!&quot; &lt;&lt; endl; mAge = age; &#125; Person(const Person&amp; p) &#123; cout &lt;&lt; &quot;拷贝构造函数!&quot; &lt;&lt; endl; mAge = p.mAge; &#125; //析构函数在释放内存之前调用 ~Person() &#123; cout &lt;&lt; &quot;析构函数!&quot; &lt;&lt; endl; &#125;public: int mAge;&#125;;//1. 使用一个已经创建完毕的对象来初始化一个新对象void test01() &#123; Person man(100); //p对象已经创建完毕 Person newman(man); //调用拷贝构造函数 Person newman2 = man; //拷贝构造 //Person newman3; //newman3 = man; //不是调用拷贝构造函数，赋值操作&#125;//2. 值传递的方式给函数参数传值//相当于Person p1 = p;void doWork(Person p1) &#123;&#125;void test02() &#123; Person p; //无参构造函数 doWork(p);&#125;//3. 以值方式返回局部对象Person doWork2()&#123; Person p1; cout &lt;&lt; (int *)&amp;p1 &lt;&lt; endl; return p1;&#125;void test03()&#123; Person p = doWork2(); cout &lt;&lt; (int *)&amp;p &lt;&lt; endl;&#125;int main() &#123; //test01(); //test02(); test03(); system(&quot;pause&quot;); return 0;&#125;
构造函数调用规则默认情况下，c++编译器至少给一个类添加3个函数 1．默认构造函数(无参，函数体为空) 2．默认析构函数(无参，函数体为空) 3．默认拷贝构造函数，对属性进行值拷贝 构造函数调用规则如下：
如果用户定义有参构造函数，c++不在提供默认无参构造，但是会提供默认拷贝构造，但要是需要创建一个类对象，必须写上默认无参构造函数
如果用户定义拷贝构造函数，c++不会再提供其他构造函数，默认构造和有参构造均不提供，析构函数还是有
示例： class Person &#123;public: //无参（默认）构造函数 Person() &#123; cout &lt;&lt; &quot;无参构造函数!&quot; &lt;&lt; endl; &#125; //有参构造函数 Person(int a) &#123; age = a; cout &lt;&lt; &quot;有参构造函数!&quot; &lt;&lt; endl; &#125; //拷贝构造函数 Person(const Person&amp; p) &#123; age = p.age; cout &lt;&lt; &quot;拷贝构造函数!&quot; &lt;&lt; endl; &#125; //析构函数 ~Person() &#123; cout &lt;&lt; &quot;析构函数!&quot; &lt;&lt; endl; &#125;public: int age;&#125;;void test01()&#123; Person p1(18); //如果不写拷贝构造，编译器会自动添加拷贝构造，并且做浅拷贝操作 Person p2(p1); cout &lt;&lt; &quot;p2的年龄为： &quot; &lt;&lt; p2.age &lt;&lt; endl;&#125;void test02()&#123; //如果用户提供有参构造，编译器不会提供默认构造，会提供拷贝构造 Person p1; //此时如果用户自己没有提供默认构造，会出错 Person p2(10); //用户提供的有参 Person p3(p2); //此时如果用户没有提供拷贝构造，编译器会提供 //如果用户提供拷贝构造，编译器不会提供其他构造函数 Person p4; //此时如果用户自己没有提供默认构造，会出错 Person p5(10); //此时如果用户自己没有提供有参，会出错 Person p6(p5); //用户自己提供拷贝构造&#125;int main() &#123; test01(); system(&quot;pause&quot;); return 0;&#125;
深拷贝与浅拷贝深浅拷贝是面试经典问题，也是常见的一个坑 浅拷贝：简单的赋值拷贝操作 深拷贝：在堆区重新申请空间，进行拷贝操作 示例： class Person &#123;public: //无参（默认）构造函数 Person() &#123; cout &lt;&lt; &quot;无参构造函数!&quot; &lt;&lt; endl; &#125; //有参构造函数 Person(int age ,int height) &#123; cout &lt;&lt; &quot;有参构造函数!&quot; &lt;&lt; endl; m_age = age; m_height = new int(height); &#125; //拷贝构造函数 Person(const Person&amp; p) &#123; cout &lt;&lt; &quot;拷贝构造函数!&quot; &lt;&lt; endl; //如果不利用深拷贝在堆区创建新内存，会导致浅拷贝带来的重复释放堆区问题 m_age = p.m_age; m_height = new int(*p.m_height); &#125; //析构函数 ~Person() &#123; cout &lt;&lt; &quot;析构函数!&quot; &lt;&lt; endl; if (m_height != NULL) &#123; delete m_height; &#125; &#125;public: int m_age; int* m_height;&#125;;void test01()&#123; Person p1(18, 180); Person p2(p1); cout &lt;&lt; &quot;p1的年龄： &quot; &lt;&lt; p1.m_age &lt;&lt; &quot; 身高： &quot; &lt;&lt; *p1.m_height &lt;&lt; endl; cout &lt;&lt; &quot;p2的年龄： &quot; &lt;&lt; p2.m_age &lt;&lt; &quot; 身高： &quot; &lt;&lt; *p2.m_height &lt;&lt; endl;&#125;int main() &#123; test01(); system(&quot;pause&quot;); return 0;&#125;
总结：如果属性有在堆区开辟的，一定要自己提供深拷贝构造函数，防止浅拷贝带来的问题
初始化列表作用： C++提供了初始化列表语法，用来初始化属性 语法：构造函数()：属性1(值1),属性2（值2）... &#123;&#125; 示例： class Person &#123;public: ////传统方式初始化 //Person(int a, int b, int c) &#123; // m_A = a; // m_B = b; // m_C = c; //&#125; //初始化列表方式初始化 Person(int a, int b, int c) :m_A(a), m_B(b), m_C(c) &#123;&#125; void PrintPerson() &#123; cout &lt;&lt; &quot;mA:&quot; &lt;&lt; m_A &lt;&lt; endl; cout &lt;&lt; &quot;mB:&quot; &lt;&lt; m_B &lt;&lt; endl; cout &lt;&lt; &quot;mC:&quot; &lt;&lt; m_C &lt;&lt; endl; &#125;private: int m_A; int m_B; int m_C;&#125;;int main() &#123; Person p(1, 2, 3); p.PrintPerson(); system(&quot;pause&quot;); return 0;&#125;
类对象作为类成员C++类中的成员可以是另一个类的对象，我们称该成员为 对象成员 例如： class A &#123;&#125;class B&#123; A a；&#125;
B类中有对象A作为成员，A为对象成员 那么当创建B对象时，A与B的构造和析构的顺序是谁先谁后？ 示例： class Phone&#123;public: Phone(string name) &#123; m_PhoneName = name; cout &lt;&lt; &quot;Phone构造&quot; &lt;&lt; endl; &#125; ~Phone() &#123; cout &lt;&lt; &quot;Phone析构&quot; &lt;&lt; endl; &#125; string m_PhoneName;&#125;;class Person&#123;public: //初始化列表可以告诉编译器调用哪一个构造函数 Person(string name, string pName) :m_Name(name), m_Phone(pName) &#123; cout &lt;&lt; &quot;Person构造&quot; &lt;&lt; endl; &#125; ~Person() &#123; cout &lt;&lt; &quot;Person析构&quot; &lt;&lt; endl; &#125; void playGame() &#123; cout &lt;&lt; m_Name &lt;&lt; &quot; 使用&quot; &lt;&lt; m_Phone.m_PhoneName &lt;&lt; &quot; 牌手机! &quot; &lt;&lt; endl; &#125; string m_Name; Phone m_Phone;&#125;;void test01()&#123; //当类中成员是其他类对象时，我们称该成员为 对象成员 //构造的顺序是 ：先调用对象成员的构造，再调用本类构造 //析构顺序与构造相反 Person p(&quot;张三&quot; , &quot;苹果X&quot;); p.playGame();&#125;int main() &#123; test01(); system(&quot;pause&quot;); return 0;&#125;
静态成员静态成员就是在成员变量和成员函数前加上关键字static，称为静态成员 静态成员分为：
静态成员变量 所有对象共享同一份数据 在编译阶段分配内存 类内声明，类外初始化
静态成员函数 所有对象共享同一个函数 静态成员函数只能访问静态成员变量
示例1 ：静态成员变量 class Person&#123; public: static int m_A; //静态成员变量 //静态成员变量特点： //1 在编译阶段分配内存 //2 类内声明，类外初始化 //3 所有对象共享同一份数据private: static int m_B; //静态成员变量也是有访问权限的&#125;;int Person::m_A = 10;int Person::m_B = 10;void test01()&#123; //静态成员变量两种访问方式 //1、通过对象 Person p1; p1.m_A = 100; cout &lt;&lt; &quot;p1.m_A = &quot; &lt;&lt; p1.m_A &lt;&lt; endl; Person p2; p2.m_A = 200; cout &lt;&lt; &quot;p1.m_A = &quot; &lt;&lt; p1.m_A &lt;&lt; endl; //共享同一份数据 cout &lt;&lt; &quot;p2.m_A = &quot; &lt;&lt; p2.m_A &lt;&lt; endl; //2、通过类名 cout &lt;&lt; &quot;m_A = &quot; &lt;&lt; Person::m_A &lt;&lt; endl; //cout &lt;&lt; &quot;m_B = &quot; &lt;&lt; Person::m_B &lt;&lt; endl; //私有权限访问不到&#125;int main() &#123; test01(); system(&quot;pause&quot;); return 0;&#125;
示例2：静态成员函数 class Person&#123;public: //静态成员函数特点： //1 程序共享一个函数 //2 静态成员函数只能访问静态成员变量 static void func() &#123; cout &lt;&lt; &quot;func调用&quot; &lt;&lt; endl; m_A = 100; //m_B = 100; //错误，不可以访问非静态成员变量 &#125; static int m_A; //静态成员变量 int m_B; // private: //静态成员函数也是有访问权限的 static void func2() &#123; cout &lt;&lt; &quot;func2调用&quot; &lt;&lt; endl; &#125;&#125;;int Person::m_A = 10;void test01()&#123; //静态成员变量两种访问方式 //1、通过对象 Person p1; p1.func(); //2、通过类名 Person::func(); //Person::func2(); //私有权限访问不到&#125;int main() &#123; test01(); system(&quot;pause&quot;); return 0;&#125;
C++对象模型和this指针成员变量和成员函数分开存储在C++中，类内的成员变量和成员函数分开存储 只有非静态成员变量才属于类的对象上 class Person &#123;public: Person() &#123; mA = 0; &#125; //非静态成员变量占对象空间 int mA; //静态成员变量不占对象空间 static int mB; //函数也不占对象空间，所有函数共享一个函数实例 void func() &#123; cout &lt;&lt; &quot;mA:&quot; &lt;&lt; this-&gt;mA &lt;&lt; endl; &#125; //静态成员函数也不占对象空间 static void sfunc() &#123; &#125;&#125;;int main() &#123; cout &lt;&lt; sizeof(Person) &lt;&lt; endl; system(&quot;pause&quot;); return 0;&#125;
this指针概念通过4.3.1我们知道在C++中成员变量和成员函数是分开存储的 每一个非静态成员函数只会诞生一份函数实例，也就是说多个同类型的对象会共用一块代码 那么问题是：这一块代码是如何区分那个对象调用自己的呢？ c++通过提供特殊的对象指针，this指针，解决上述问题。this指针指向被调用的成员函数所属的对象 this指针是隐含每一个非静态成员函数内的一种指针 this指针不需要定义，直接使用即可 this指针的用途：
当形参和成员变量同名时，可用this指针来区分 在类的非静态成员函数中返回对象本身，可使用return *this
class Person&#123;public: Person(int age) &#123; //1、当形参和成员变量同名时，可用this指针来区分 //this指针指向被调用的成员函数所属的对象 this-&gt;age = age; &#125; Person&amp; PersonAddPerson(Person p) &#123; this-&gt;age += p.age; //this指向p2的指针，而*this指向的就是p2对象的本体 return *this; &#125; int age;&#125;;void test01()&#123; Person p1(10); cout &lt;&lt; &quot;p1.age = &quot; &lt;&lt; p1.age &lt;&lt; endl; Person p2(10); //链式变成思想 p2.PersonAddPerson(p1).PersonAddPerson(p1).PersonAddPerson(p1); cout &lt;&lt; &quot;p2.age = &quot; &lt;&lt; p2.age &lt;&lt; endl;&#125;int main() &#123; test01(); system(&quot;pause&quot;); return 0;&#125;
空指针访问成员函数C++中空指针也是可以调用成员函数的，但是也要注意有没有用到this指针 如果用到this指针，需要加以判断保证代码的健壮性 示例： //空指针访问成员函数class Person &#123;public: void ShowClassName() &#123; cout &lt;&lt; &quot;我是Person类!&quot; &lt;&lt; endl; &#125; void ShowPerson() &#123; if (this == NULL) &#123; return; &#125; cout &lt;&lt; mAge &lt;&lt; endl; //mAge相当于this-&gt;mAge，但是当p-&gt;ShowPerson()调用这个函数的时候，因为此时*p指向一个空的值，并不是一个确定的对象，无法访问Person属性的成员变量 &#125;public: int mAge;&#125;;void test01()&#123; Person * p = NULL; p-&gt;ShowClassName(); //空指针，可以调用成员函数 p-&gt;ShowPerson(); //但是如果成员函数中用到了this指针，就不可以了&#125;int main() &#123; test01(); system(&quot;pause&quot;); return 0;&#125;
const修饰成员函数常函数：
成员函数后加const后我们称为这个函数为常函数 常函数内不可以修改成员属性 成员属性声明时加关键字mutable后，在常函数中依然可以修改
常对象：
声明对象前加const称该对象为常对象 常对象只能调用常函数
示例： class Person &#123;public: Person() &#123; m_A = 0; m_B = 0; &#125; //this指针的本质是一个指针常量，指针的指向不可修改 //如果想让指针指向的值也不可以修改，需要声明常函数 //在成员函数的后面加const，修饰的是this指向，让this指向的 值 也不可以进行修改 void ShowPerson() const &#123; //const Type* const pointer; //this = NULL; //不能修改指针的指向 Person* const this; //this-&gt;mA = 100; //但是this指针指向的对象的数据是可以修改的 //const修饰成员函数，表示指针指向的内存空间的数据不能修改，除了mutable修饰的变量 this-&gt;m_B = 100; &#125; void MyFunc() const &#123; //mA = 10000; &#125;public: int m_A; mutable int m_B; //加mutable之后，此属性可修改 可变的&#125;;//const修饰对象 常对象void test01() &#123; const Person person; //常量对象 cout &lt;&lt; person.m_A &lt;&lt; endl; //person.mA = 100; //常对象不能修改成员变量的值,但是可以访问 person.m_B = 100; //但是常对象可以修改mutable修饰成员变量 //常对象访问成员函数 person.MyFunc(); //常对象只能调用常函数，常对象不能调用普通的成员函数，因为普通成员函数能修改&#125;int main() &#123; test01(); system(&quot;pause&quot;); return 0;&#125;
友元生活中你的家有客厅(Public)，有你的卧室(Private) 客厅所有来的客人都可以进去，但是你的卧室是私有的，也就是说只有你能进去 但是呢，你也可以允许你的好闺蜜好基友进去。 在程序里，有些私有属性 也想让类外特殊的一些函数或者类进行访问，就需要用到友元的技术 友元的目的就是让一个函数或者类 访问另一个类中私有成员 友元的关键字为 ==friend== 友元的三种实现
全局函数做友元 类做友元 成员函数做友元
全局函数做友元class Building&#123; //告诉编译器 goodGay全局函数 是 Building类的好朋友，可以访问类中的私有内容 friend void goodGay(Building * building);public: Building() &#123; this-&gt;m_SittingRoom = &quot;客厅&quot;; this-&gt;m_BedRoom = &quot;卧室&quot;; &#125;public: string m_SittingRoom; //客厅private: string m_BedRoom; //卧室&#125;;void goodGay(Building * building)&#123; cout &lt;&lt; &quot;好基友正在访问： &quot; &lt;&lt; building-&gt;m_SittingRoom &lt;&lt; endl; cout &lt;&lt; &quot;好基友正在访问： &quot; &lt;&lt; building-&gt;m_BedRoom &lt;&lt; endl;&#125;void test01()&#123; Building b; goodGay(&amp;b);&#125;int main()&#123; test01(); system(&quot;pause&quot;); return 0;&#125;
类做友元class Building;class goodGay&#123;public: goodGay(); void visit();private: Building *building;&#125;;class Building&#123; //告诉编译器 goodGay类是Building类的好朋友，可以访问到Building类中私有内容 friend class goodGay;public: Building();public: string m_SittingRoom; //客厅private: string m_BedRoom;//卧室&#125;;Building::Building()&#123; this-&gt;m_SittingRoom = &quot;客厅&quot;; this-&gt;m_BedRoom = &quot;卧室&quot;;&#125;goodGay::goodGay()&#123; building = new Building;&#125;void goodGay::visit()&#123; cout &lt;&lt; &quot;好基友正在访问&quot; &lt;&lt; building-&gt;m_SittingRoom &lt;&lt; endl; cout &lt;&lt; &quot;好基友正在访问&quot; &lt;&lt; building-&gt;m_BedRoom &lt;&lt; endl;&#125;void test01()&#123; goodGay gg; gg.visit();&#125;int main()&#123; test01(); system(&quot;pause&quot;); return 0;&#125;
成员函数做友元class Building;class goodGay&#123;public: goodGay(); void visit(); //只让visit函数作为Building的好朋友，可以发访问Building中私有内容 void visit2(); private: Building *building;&#125;;class Building&#123; //告诉编译器 goodGay类中的visit成员函数 是Building好朋友，可以访问私有内容 friend void goodGay::visit();public: Building();public: string m_SittingRoom; //客厅private: string m_BedRoom;//卧室&#125;;Building::Building()&#123; this-&gt;m_SittingRoom = &quot;客厅&quot;; this-&gt;m_BedRoom = &quot;卧室&quot;;&#125;goodGay::goodGay()&#123; building = new Building;&#125;void goodGay::visit()&#123; cout &lt;&lt; &quot;好基友正在访问&quot; &lt;&lt; building-&gt;m_SittingRoom &lt;&lt; endl; cout &lt;&lt; &quot;好基友正在访问&quot; &lt;&lt; building-&gt;m_BedRoom &lt;&lt; endl;&#125;void goodGay::visit2()&#123; cout &lt;&lt; &quot;好基友正在访问&quot; &lt;&lt; building-&gt;m_SittingRoom &lt;&lt; endl; //cout &lt;&lt; &quot;好基友正在访问&quot; &lt;&lt; building-&gt;m_BedRoom &lt;&lt; endl;&#125;void test01()&#123; goodGay gg; gg.visit();&#125;int main()&#123; test01(); system(&quot;pause&quot;); return 0;&#125;
运算符重载运算符重载概念：对已有的运算符重新进行定义，赋予其另一种功能，以适应不同的数据类型 下面我就拿两个例子简单示例一下，当然还有**++运算符**等重载，有兴趣的小伙伴可以去自己上网或者查询书籍深入了解一下 加号运算符重载作用：实现两个自定义数据类型相加的运算 class Person &#123;public: Person() &#123;&#125;; Person(int a, int b) &#123; this-&gt;m_A = a; this-&gt;m_B = b; &#125; //成员函数实现 + 号运算符重载 Person operator+(const Person&amp; p) &#123; Person temp; temp.m_A = this-&gt;m_A + p.m_A; temp.m_B = this-&gt;m_B + p.m_B; return temp; &#125;public: int m_A; int m_B;&#125;;//全局函数实现 + 号运算符重载//Person operator+(const Person&amp; p1, const Person&amp; p2) &#123;// Person temp(0, 0);// temp.m_A = p1.m_A + p2.m_A;// temp.m_B = p1.m_B + p2.m_B;// return temp;//&#125;//运算符重载 可以发生函数重载 Person operator+(const Person&amp; p2, int val) &#123; Person temp; temp.m_A = p2.m_A + val; temp.m_B = p2.m_B + val; return temp;&#125;void test() &#123; //对类对象p1，p2的m_A,m_B属性分别进行初始化 Person p1(10, 10); Person p2(20, 20); //成员函数Person operator+(const Person&amp; p)的调用 Person p3 = p2 + p1; //相当于 p2.operaor+(p1) cout &lt;&lt; &quot;mA:&quot; &lt;&lt; p3.m_A &lt;&lt; &quot; mB:&quot; &lt;&lt; p3.m_B &lt;&lt; endl; //全局函数operator+的调用 Person p4 = p3 + 10; //相当于 operator+(p3,10) cout &lt;&lt; &quot;mA:&quot; &lt;&lt; p4.m_A &lt;&lt; &quot; mB:&quot; &lt;&lt; p4.m_B &lt;&lt; endl;&#125;int main() &#123; test(); system(&quot;pause&quot;); return 0;&#125;
总结1：对于内置的数据类型的表达式的的运算符是不可能改变的
总结2：不要滥用运算符重载
左移运算符重载作用：可以输出自定义数据类型 class Person &#123; friend ostream&amp; operator&lt;&lt;(ostream&amp; out, Person&amp; p);public: Person(int a, int b) &#123; this-&gt;m_A = a; this-&gt;m_B = b; &#125; //成员函数 实现不了 p &lt;&lt; cout 不是我们想要的效果 //void operator&lt;&lt;(Person&amp; p)&#123; //&#125;private: int m_A; int m_B;&#125;;//全局函数实现左移重载//ostream对象只能有一个ostream&amp; operator&lt;&lt;(ostream&amp; out, Person&amp; p) &#123; out &lt;&lt; &quot;a:&quot; &lt;&lt; p.m_A &lt;&lt; &quot; b:&quot; &lt;&lt; p.m_B; return out;&#125;void test() &#123; Person p1(10, 20); cout &lt;&lt; p1 &lt;&lt; &quot;hello world&quot; &lt;&lt; endl; //链式编程&#125;int main() &#123; test(); system(&quot;pause&quot;); return 0;&#125;
总结：重载左移运算符配合友元可以实现输出自定义数据类型
继承继承是面向对象三大特性之一 我们发现，定义很多类时，下级别的成员除了拥有上一级的共性，还有自己的特性。 这个时候我们就可以考虑利用继承的技术，减少重复代码 继承的基本语法例如我们看到很多网站中，都有公共的头部，公共的底部，甚至公共的左侧列表，只有中心内容不同 接下来我们分别利用普通写法和继承的写法来实现网页中的内容，看一下继承存在的意义以及好处 普通实现： //Java页面class Java &#123;public: void header() &#123; cout &lt;&lt; &quot;首页、公开课、登录、注册...（公共头部）&quot; &lt;&lt; endl; &#125; void footer() &#123; cout &lt;&lt; &quot;帮助中心、交流合作、站内地图...(公共底部)&quot; &lt;&lt; endl; &#125; void left() &#123; cout &lt;&lt; &quot;Java,Python,C++...(公共分类列表)&quot; &lt;&lt; endl; &#125; void content() &#123; cout &lt;&lt; &quot;JAVA学科视频&quot; &lt;&lt; endl; &#125;&#125;;//Python页面class Python&#123;public: void header() &#123; cout &lt;&lt; &quot;首页、公开课、登录、注册...（公共头部）&quot; &lt;&lt; endl; &#125; void footer() &#123; cout &lt;&lt; &quot;帮助中心、交流合作、站内地图...(公共底部)&quot; &lt;&lt; endl; &#125; void left() &#123; cout &lt;&lt; &quot;Java,Python,C++...(公共分类列表)&quot; &lt;&lt; endl; &#125; void content() &#123; cout &lt;&lt; &quot;Python学科视频&quot; &lt;&lt; endl; &#125;&#125;;//C++页面class CPP &#123;public: void header() &#123; cout &lt;&lt; &quot;首页、公开课、登录、注册...（公共头部）&quot; &lt;&lt; endl; &#125; void footer() &#123; cout &lt;&lt; &quot;帮助中心、交流合作、站内地图...(公共底部)&quot; &lt;&lt; endl; &#125; void left() &#123; cout &lt;&lt; &quot;Java,Python,C++...(公共分类列表)&quot; &lt;&lt; endl; &#125; void content() &#123; cout &lt;&lt; &quot;C++学科视频&quot; &lt;&lt; endl; &#125;&#125;;void test01()&#123; //Java页面 cout &lt;&lt; &quot;Java下载视频页面如下： &quot; &lt;&lt; endl; Java ja; ja.header(); ja.footer(); ja.left(); ja.content(); cout &lt;&lt; &quot;--------------------&quot; &lt;&lt; endl; //Python页面 cout &lt;&lt; &quot;Python下载视频页面如下： &quot; &lt;&lt; endl; Python py; py.header(); py.footer(); py.left(); py.content(); cout &lt;&lt; &quot;--------------------&quot; &lt;&lt; endl; //C++页面 cout &lt;&lt; &quot;C++下载视频页面如下： &quot; &lt;&lt; endl; CPP cp; cp.header(); cp.footer(); cp.left(); cp.content();&#125;int main() &#123; test01(); system(&quot;pause&quot;); return 0;&#125;
继承实现： //公共页面class BasePage&#123;public: void header() &#123; cout &lt;&lt; &quot;首页、公开课、登录、注册...（公共头部）&quot; &lt;&lt; endl; &#125; void footer() &#123; cout &lt;&lt; &quot;帮助中心、交流合作、站内地图...(公共底部)&quot; &lt;&lt; endl; &#125; void left() &#123; cout &lt;&lt; &quot;Java,Python,C++...(公共分类列表)&quot; &lt;&lt; endl; &#125;&#125;;//Java页面class Java : public BasePage&#123;public: void content() &#123; cout &lt;&lt; &quot;JAVA学科视频&quot; &lt;&lt; endl; &#125;&#125;;//Python页面class Python : public BasePage&#123;public: void content() &#123; cout &lt;&lt; &quot;Python学科视频&quot; &lt;&lt; endl; &#125;&#125;;//C++页面class CPP : public BasePage&#123;public: void content() &#123; cout &lt;&lt; &quot;C++学科视频&quot; &lt;&lt; endl; &#125;&#125;;void test01()&#123; //Java页面 cout &lt;&lt; &quot;Java下载视频页面如下： &quot; &lt;&lt; endl; Java ja; ja.header(); ja.footer(); ja.left(); ja.content(); cout &lt;&lt; &quot;--------------------&quot; &lt;&lt; endl; //Python页面 cout &lt;&lt; &quot;Python下载视频页面如下： &quot; &lt;&lt; endl; Python py; py.header(); py.footer(); py.left(); py.content(); cout &lt;&lt; &quot;--------------------&quot; &lt;&lt; endl; //C++页面 cout &lt;&lt; &quot;C++下载视频页面如下： &quot; &lt;&lt; endl; CPP cp; cp.header(); cp.footer(); cp.left(); cp.content();&#125;int main() &#123; test01(); system(&quot;pause&quot;); return 0;&#125;
总结： 继承的好处：==可以减少重复的代码== class A : public B; A 类称为子类 或 派生类 B 类称为父类 或 基类 派生类中的成员，包含两大部分： 一类是从基类继承过来的，一类是自己增加的成员。 从基类继承过过来的表现其共性，而新增的成员体现了其个性。 继承方式继承的语法：class 子类 : 继承方式 父类 继承方式一共有三种：
公共继承 保护继承 私有继承
示例： class Base1&#123;public: int m_A;protected: int m_B;private: int m_C;&#125;;//公共继承class Son1 :public Base1&#123;public: void func() &#123; m_A; //可访问 public权限 m_B; //可访问 protected权限 //m_C; //不可访问 &#125;&#125;;void myClass()&#123; Son1 s1; s1.m_A; //其他类只能访问到公共权限&#125;//保护继承class Base2&#123;public: int m_A;protected: int m_B;private: int m_C;&#125;;class Son2:protected Base2&#123;public: void func() &#123; m_A; //可访问 protected权限 m_B; //可访问 protected权限 //m_C; //不可访问 &#125;&#125;;void myClass2()&#123; Son2 s; //s.m_A; //不可访问&#125;//私有继承class Base3&#123;public: int m_A;protected: int m_B;private: int m_C;&#125;;class Son3:private Base3&#123;public: void func() &#123; m_A; //可访问 private权限 m_B; //可访问 private权限 //m_C; //不可访问 &#125;&#125;;class GrandSon3 :public Son3&#123;public: void func() &#123; //Son3是私有继承，所以继承Son3的属性在GrandSon3中都无法访问到 //m_A; //m_B; //m_C; &#125;&#125;;
继承中的对象模型示例： class Base&#123;public: int m_A;protected: int m_B;private: int m_C; //私有成员只是被隐藏了，但是还是会继承下去&#125;;//公共继承class Son :public Base&#123;public: int m_D;&#125;;void test01()&#123; //父类中的非静态成员属性都会被子类继承，只不过父类的private 被隐藏了 //子类可以继承父类的静态属性 cout &lt;&lt; &quot;sizeof Son = &quot; &lt;&lt; sizeof(Son) &lt;&lt; endl;&#125;int main() &#123; test01(); system(&quot;pause&quot;); return 0;&#125;
利用工具查看： 1、找到visual studio下面的vs2017的开发人员命令指示符 2、打开工具窗口后，定位到当前CPP文件的盘符，假如你的cpp文件在F盘那就先输入F: 3、然后输入cd 你的以.cpp为后缀代码文件的文件夹 4、然后输入dir,查看此文件夹中的文件目录 5、输入cl /d1 reportSingleClassLayout查看的类名 “所属文件名” （cl是字母cl，/d后面的是数字1，而且cl 和/d1之间有空格）
结论： 父类中私有成员也是被子类继承下去了，只是由编译器给隐藏后访问不到
继承中构造和析构顺序子类继承父类后，当创建子类对象，也会调用父类的构造函数 问题：父类和子类的构造和析构顺序是谁先谁后？ 示例： class Base &#123;public: Base() &#123; cout &lt;&lt; &quot;Base构造函数!&quot; &lt;&lt; endl; &#125; ~Base() &#123; cout &lt;&lt; &quot;Base析构函数!&quot; &lt;&lt; endl; &#125;&#125;;class Son : public Base&#123;public: Son() &#123; cout &lt;&lt; &quot;Son构造函数!&quot; &lt;&lt; endl; &#125; ~Son() &#123; cout &lt;&lt; &quot;Son析构函数!&quot; &lt;&lt; endl; &#125;&#125;;void test01()&#123; //继承中 先调用父类构造函数，再调用子类构造函数，析构顺序与构造相反 Son s;&#125;int main() &#123; test01(); system(&quot;pause&quot;); return 0;&#125;
总结：继承中 先调用父类构造函数，再调用子类构造函数，析构顺序与构造相反 ​ 就是类似于先有爸爸，才生的出来儿子一样的
继承同名成员处理方式问题：当子类与父类出现同名的成员，如何通过子类对象，访问到子类或父类中同名的数据呢？
访问子类同名成员 直接访问即可 访问父类同名成员 需要加作用域，格式即：类对象.父类类名 :: 父类中同名的函数( );
示例： class Base &#123;public: Base() &#123; m_A = 100; &#125; void func() &#123; cout &lt;&lt; &quot;Base - func()调用&quot; &lt;&lt; endl; &#125; void func(int a) &#123; cout &lt;&lt; &quot;Base - func(int a)调用&quot; &lt;&lt; endl; &#125;public: int m_A;&#125;;class Son : public Base &#123;public: Son() &#123; m_A = 200; &#125; //当子类与父类拥有同名的成员函数，子类会隐藏父类中所有版本的同名成员函数 //如果想访问父类中被隐藏的同名成员函数，需要加父类的作用域 void func() &#123; cout &lt;&lt; &quot;Son - func()调用&quot; &lt;&lt; endl; &#125;public: int m_A;&#125;;void test01()&#123; Son s; cout &lt;&lt; &quot;Son下的m_A = &quot; &lt;&lt; s.m_A &lt;&lt; endl; cout &lt;&lt; &quot;Base下的m_A = &quot; &lt;&lt; s.Base::m_A &lt;&lt; endl; s.func(); s.Base::func(); s.Base::func(10);&#125;int main() &#123; test01(); system(&quot;pause&quot;); return EXIT_SUCCESS;&#125;
总结：
子类对象可以直接访问到子类中同名成员 子类对象加作用域可以访问到父类同名成员 当子类与父类拥有同名的成员函数，子类会隐藏父类中同名成员函数，加作用域可以访问到父类中同名函数
继承同名静态成员处理方式问题：继承中同名的静态成员在子类对象上如何进行访问？ 静态成员和非静态成员出现同名，处理方式一致
访问子类同名成员 直接访问即可 访问父类同名成员 需要加作用域
示例： class Base &#123;public: static void func() &#123; cout &lt;&lt; &quot;Base - static void func()&quot; &lt;&lt; endl; &#125; static void func(int a) &#123; cout &lt;&lt; &quot;Base - static void func(int a)&quot; &lt;&lt; endl; &#125; static int m_A;&#125;;int Base::m_A = 100;class Son : public Base &#123;public: static void func() &#123; cout &lt;&lt; &quot;Son - static void func()&quot; &lt;&lt; endl; &#125; static int m_A;&#125;;int Son::m_A = 200;//同名成员属性void test01()&#123; //通过对象访问 cout &lt;&lt; &quot;通过对象访问： &quot; &lt;&lt; endl; Son s; cout &lt;&lt; &quot;Son 下 m_A = &quot; &lt;&lt; s.m_A &lt;&lt; endl; cout &lt;&lt; &quot;Base 下 m_A = &quot; &lt;&lt; s.Base::m_A &lt;&lt; endl; //通过类名访问 cout &lt;&lt; &quot;通过类名访问： &quot; &lt;&lt; endl; cout &lt;&lt; &quot;Son 下 m_A = &quot; &lt;&lt; Son::m_A &lt;&lt; endl; //第一个：：代表通过类名的方式访问 第二个::代表访问父类作用域下 cout &lt;&lt; &quot;Base 下 m_A = &quot; &lt;&lt; Son::Base::m_A &lt;&lt; endl;&#125;//同名成员函数void test02()&#123; //通过对象访问 cout &lt;&lt; &quot;通过对象访问： &quot; &lt;&lt; endl; Son s; s.func(); s.Base::func(); //子类类名::父类类名::父类静态成员函数 cout &lt;&lt; &quot;通过类名访问： &quot; &lt;&lt; endl; Son::func(); Son::Base::func(); //出现同名，子类会隐藏掉父类中所有同名成员函数，需要加作作用域访问 Son::Base::func(100);&#125;int main() &#123; //test01(); test02(); system(&quot;pause&quot;); return 0;&#125;
总结：同名静态成员处理方式和非静态处理方式一样，只不过有两种访问的方式（通过对象 和 通过类名） ​ 切记在类外访问类内非静态成员函数的时候，不能通过类名::函数名的方式直接访问，并且静态成员函数只能访问静态成员变量
多继承语法C++允许一个类继承多个类 语法： class 子类 ：继承方式 父类1 ， 继承方式 父类2... 多继承可能会引发父类中有同名成员出现，需要加作用域区分 C++实际开发中不建议用多继承 示例： class Base1 &#123;public: Base1() &#123; m_A = 100; &#125;public: int m_A;&#125;;class Base2 &#123;public: Base2() &#123; m_A = 200; //开始是m_B 不会出问题，但是改为mA就会出现不明确 &#125;public: int m_A;&#125;;//语法：class 子类：继承方式 父类1 ，继承方式 父类2 class Son : public Base2, public Base1 &#123;public: Son() &#123; m_C = 300; m_D = 400; &#125;public: int m_C; int m_D;&#125;;//多继承容易产生成员同名的情况//通过使用类名作用域可以区分调用哪一个基类的成员void test01()&#123; //当父类中出现同名的成员，需要加作用域进行区分 Son s; cout &lt;&lt; &quot;sizeof Son = &quot; &lt;&lt; sizeof(s) &lt;&lt; endl; cout &lt;&lt; s.Base1::m_A &lt;&lt; endl; cout &lt;&lt; s.Base2::m_A &lt;&lt; endl;&#125;int main() &#123; test01(); system(&quot;pause&quot;); return 0;&#125;
总结： 多继承中如果父类中出现了同名情况，子类使用时候要加作用域
菱形继承菱形继承概念： ​ 两个派生类继承同一个基类 ​ 又有某个类同时继承者两个派生类 ​ 这种继承被称为菱形继承，或者钻石继承 菱形继承问题：
羊继承了动物的数据，驼同样继承了动物的数据，当草泥马使用数据时，就会产生二义性。
草泥马继承自动物的数据继承了两份，其实我们应该清楚，这份数据我们只需要一份就可以。
示例： class Animal&#123;public: int m_Age;&#125;;//继承前加virtual关键字后，变为虚继承//此时公共的父类Animal称为虚基类class Sheep : virtual public Animal &#123;&#125;;class Tuo : virtual public Animal &#123;&#125;;class SheepTuo : public Sheep, public Tuo &#123;&#125;;void test01()&#123; SheepTuo st; st.Sheep::m_Age = 100; st.Tuo::m_Age = 200; cout &lt;&lt; &quot;st.Sheep::m_Age = &quot; &lt;&lt; st.Sheep::m_Age &lt;&lt; endl; cout &lt;&lt; &quot;st.Tuo::m_Age = &quot; &lt;&lt; st.Tuo::m_Age &lt;&lt; endl; cout &lt;&lt; &quot;st.m_Age = &quot; &lt;&lt; st.m_Age &lt;&lt; endl;&#125;int main() &#123; test01(); system(&quot;pause&quot;); return 0;&#125;
总结：
菱形继承带来的主要问题是子类继承两份相同的数据，导致资源浪费以及毫无意义 利用虚继承可以解决菱形继承问题
多态多态的基本概念多态是C++面向对象三大特性之一 多态分为两类
静态多态: 函数重载 和 运算符重载属于静态多态，复用函数名 动态多态: 派生类和虚函数实现运行时多态
静态多态和动态多态区别：
静态多态的函数地址早绑定 - 编译阶段确定函数地址 动态多态的函数地址晚绑定 - 运行阶段确定函数地址
下面通过案例进行讲解多态 class Animal&#123;public: //Speak函数就是虚函数，此时的animal类的Speak也就是动态化的一个函数 //函数前面加上virtual关键字，变成虚函数，那么编译器在编译的时候就不能确定函数调用了，就会根据运行阶段进行函数的地址，实现晚绑定 virtual void speak() &#123; cout &lt;&lt; &quot;动物在说话&quot; &lt;&lt; endl; &#125;&#125;;class Cat :public Animal&#123;public: void speak() &#123; cout &lt;&lt; &quot;小猫在说话&quot; &lt;&lt; endl; &#125;&#125;;class Dog :public Animal&#123;public: void speak() &#123; cout &lt;&lt; &quot;小狗在说话&quot; &lt;&lt; endl; &#125;&#125;;//我们希望传入什么对象，那么就调用什么对象的函数//如果函数地址在编译阶段就能确定，那么静态联编//如果函数地址在运行阶段才能确定，就是动态联编void DoSpeak(Animal &amp; animal)&#123; animal.speak();&#125;void test01()&#123; Cat cat; DoSpeak(cat);//Animal &amp;animal = cat Dog dog; DoSpeak(dog);&#125;int main() &#123; test01(); system(&quot;pause&quot;); return 0;&#125;//多态满足条件： //1、有继承关系//2、子类重写父类中的虚函数，但是不要加virtual//多态使用：//父类的 指针 或 引用 指向子类对象
总结： 多态满足条件
有继承关系 子类重写父类中的虚函数
多态使用条件
父类指针或引用指向子类对象
重写：函数返回值类型 函数名 参数列表 完全一致称为重写 多态案例一-计算器类案例描述： 分别利用普通写法和多态技术，设计实现两个操作数进行运算的计算器类 多态的优点：
代码组织结构清晰 可读性强 利于前期和后期的扩展以及维护
示例： //普通实现class Calculator &#123;public: int getResult(string oper) &#123; if (oper == &quot;+&quot;) &#123; return m_Num1 + m_Num2; &#125; else if (oper == &quot;-&quot;) &#123; return m_Num1 - m_Num2; &#125; else if (oper == &quot;*&quot;) &#123; return m_Num1 * m_Num2; &#125; //如果要提供新的运算，需要修改源码 &#125;public: int m_Num1; int m_Num2;&#125;;void test01()&#123; //普通实现测试 Calculator c; c.m_Num1 = 10; c.m_Num2 = 10; cout &lt;&lt; c.m_Num1 &lt;&lt; &quot; + &quot; &lt;&lt; c.m_Num2 &lt;&lt; &quot; = &quot; &lt;&lt; c.getResult(&quot;+&quot;) &lt;&lt; endl; cout &lt;&lt; c.m_Num1 &lt;&lt; &quot; - &quot; &lt;&lt; c.m_Num2 &lt;&lt; &quot; = &quot; &lt;&lt; c.getResult(&quot;-&quot;) &lt;&lt; endl; cout &lt;&lt; c.m_Num1 &lt;&lt; &quot; * &quot; &lt;&lt; c.m_Num2 &lt;&lt; &quot; = &quot; &lt;&lt; c.getResult(&quot;*&quot;) &lt;&lt; endl;&#125;//多态实现//抽象计算器类//多态优点：代码组织结构清晰，可读性强，利于前期和后期的扩展以及维护class AbstractCalculator&#123;public : virtual int getResult() &#123; return 0; &#125; int m_Num1; int m_Num2;&#125;;//加法计算器class AddCalculator :public AbstractCalculator&#123;public: int getResult() &#123; return m_Num1 + m_Num2; &#125;&#125;;//减法计算器class SubCalculator :public AbstractCalculator&#123;public: int getResult() &#123; return m_Num1 - m_Num2; &#125;&#125;;//乘法计算器class MulCalculator :public AbstractCalculator&#123;public: int getResult() &#123; return m_Num1 * m_Num2; &#125;&#125;;void test02()&#123; //创建加法计算器 AbstractCalculator *abc = new AddCalculator; abc-&gt;m_Num1 = 10; abc-&gt;m_Num2 = 10; cout &lt;&lt; abc-&gt;m_Num1 &lt;&lt; &quot; + &quot; &lt;&lt; abc-&gt;m_Num2 &lt;&lt; &quot; = &quot; &lt;&lt; abc-&gt;getResult() &lt;&lt; endl; delete abc; //用完了记得销毁，只是把堆区的abc的值删除了，但是abc的指针并没有删除，故后面直接用abc指向新的对象即可。 //创建减法计算器 abc = new SubCalculator; abc-&gt;m_Num1 = 10; abc-&gt;m_Num2 = 10; cout &lt;&lt; abc-&gt;m_Num1 &lt;&lt; &quot; - &quot; &lt;&lt; abc-&gt;m_Num2 &lt;&lt; &quot; = &quot; &lt;&lt; abc-&gt;getResult() &lt;&lt; endl; delete abc; //创建乘法计算器 abc = new MulCalculator; abc-&gt;m_Num1 = 10; abc-&gt;m_Num2 = 10; cout &lt;&lt; abc-&gt;m_Num1 &lt;&lt; &quot; * &quot; &lt;&lt; abc-&gt;m_Num2 &lt;&lt; &quot; = &quot; &lt;&lt; abc-&gt;getResult() &lt;&lt; endl; delete abc;&#125;int main() &#123; //test01(); test02(); system(&quot;pause&quot;); return 0;&#125;
总结：
C++多态组织结构清晰，可读性强，便于前后期的扩展以及维护 使用条件：父类的 “指针” 或者 “子类” 指向子类对象
纯虚函数和抽象类在多态中，通常父类中虚函数的实现是毫无意义的，主要都是调用子类重写的内容，如果父类中的虚函数对项目的开发毫无用处，那就可以定义成一个纯虚函数进行开发 纯虚函数语法：virtual 返回值类型 函数名 （参数列表）= 0 ; 当类中有了纯虚函数，这个类也称为抽象类 抽象类特点：
无法实例化对象，只能通过指针 子类必须重写抽象（父）类中的纯虚函数，否则也属于抽象类
示例： class Base&#123;public: //纯虚函数 //类中只要有一个纯虚函数就称为抽象类 //1、抽象类无法实例化对象 //2、子类必须重写父类中的纯虚函数，否则也属于抽象类，无法实例化对象 virtual void func() = 0;&#125;;class Son :public Base&#123;public: virtual void func() &#123; cout &lt;&lt; &quot;func调用&quot; &lt;&lt; endl; &#125;;&#125;;void test01()&#123; Base * base = NULL; //base = new Base; // 错误，抽象类无法实例化对象 base = new Son;//或者Base * base = NULL;base = new Son;写成一句话 Base * base = new Son; base-&gt;func(); delete base;//记得销毁.释放base指针的值&#125;int main() &#123; test01(); system(&quot;pause&quot;); return 0;&#125;
多态案例二-制作饮品案例描述： 制作饮品的大致流程为：煮水 - 冲泡 - 倒入杯中 - 加入辅料 利用多态技术实现本案例，提供抽象制作饮品基类，提供子类制作咖啡和茶叶，实现烧、冲、倒、加等功能 示例： //抽象制作饮品class AbstractDrinking &#123;public: //烧水 virtual void Boil() = 0; //冲泡 virtual void Brew() = 0; //倒入杯中 virtual void PourInCup() = 0; //加入辅料 virtual void PutSomething() = 0; //规定流程 void MakeDrink() &#123; Boil(); Brew(); PourInCup(); PutSomething(); &#125;&#125;;//制作咖啡class Coffee : public AbstractDrinking &#123;public: //烧水 virtual void Boil() &#123; cout &lt;&lt; &quot;煮农夫山泉!&quot; &lt;&lt; endl; &#125; //冲泡 virtual void Brew() &#123; cout &lt;&lt; &quot;冲泡咖啡!&quot; &lt;&lt; endl; &#125; //倒入杯中 virtual void PourInCup() &#123; cout &lt;&lt; &quot;将咖啡倒入杯中!&quot; &lt;&lt; endl; &#125; //加入辅料 virtual void PutSomething() &#123; cout &lt;&lt; &quot;加入牛奶!&quot; &lt;&lt; endl; &#125;&#125;;//制作茶水class Tea : public AbstractDrinking &#123;public: //烧水 virtual void Boil() &#123; cout &lt;&lt; &quot;煮自来水!&quot; &lt;&lt; endl; &#125; //冲泡 virtual void Brew() &#123; cout &lt;&lt; &quot;冲泡茶叶!&quot; &lt;&lt; endl; &#125; //倒入杯中 virtual void PourInCup() &#123; cout &lt;&lt; &quot;将茶水倒入杯中!&quot; &lt;&lt; endl; &#125; //加入辅料 virtual void PutSomething() &#123; cout &lt;&lt; &quot;加入枸杞!&quot; &lt;&lt; endl; &#125;&#125;;//业务函数void DoWork(AbstractDrinking* drink) &#123; drink-&gt;MakeDrink(); delete drink;&#125;void test01() &#123; DoWork(new Coffee);//即让void DoWork(AbstractDrinking* drink)中的* drink指针指向Coffee并调用DoWork函数，此时Coffee便会调用继承下来的void MakeDrink()和已经重写好的void MakeDrink()函数中的烧、冲、倒、加等功能 cout &lt;&lt; &quot;--------------&quot; &lt;&lt; endl; DoWork(new Tea);//同理&#125;int main() &#123; test01(); system(&quot;pause&quot;); return 0;&#125;
虚析构和纯虚析构多态使用时，如果子类中有属性开辟到堆区，那么父类指针在释放时无法调用到子类的析构代码 解决方式：将父类中的析构函数改为虚析构或者纯虚析构 虚析构和纯虚析构共性：
可以解决父类指针释放子类对象 都需要有具体的函数实现
虚析构和纯虚析构区别：
如果是纯虚析构，该类属于抽象类，无法实例化对象
虚析构语法： virtual ~类名()&#123;&#125; 纯虚析构语法： virtual ~类名() = 0; 类名::~类名()&#123;&#125; 示例： class Animal &#123;public: Animal() &#123; cout &lt;&lt; &quot;Animal 构造函数调用！&quot; &lt;&lt; endl; &#125; virtual void Speak() = 0; //析构函数加上virtual关键字，变成虚析构函数，来解决父类指针释放子类对象不干净的问题 //virtual ~Animal() //&#123; // cout &lt;&lt; &quot;Animal虚析构函数调用！&quot; &lt;&lt; endl; //&#125; //纯虚析构函数，但是需要对此纯虚构函数进行 声明和实现 virtual ~Animal() = 0;&#125;;Animal::~Animal()&#123; cout &lt;&lt; &quot;Animal 纯虚析构函数调用！&quot; &lt;&lt; endl;&#125;//和包含普通纯虚函数的类一样，包含了纯虚析构函数的类也是一个抽象类。不能够被实例化。class Cat : public Animal &#123;public: Cat(string name) &#123; cout &lt;&lt; &quot;Cat构造函数调用！&quot; &lt;&lt; endl; m_Name = new string(name); &#125; virtual void Speak() &#123; cout &lt;&lt; *m_Name &lt;&lt; &quot;小猫在说话!&quot; &lt;&lt; endl; &#125; ~Cat() &#123; cout &lt;&lt; &quot;Cat析构函数调用!&quot; &lt;&lt; endl; if (this-&gt;m_Name != NULL) &#123; delete m_Name; m_Name = NULL; &#125; &#125;public: string *m_Name;&#125;;void test01()&#123; Animal *animal = new Cat(&quot;Tom&quot;); animal-&gt;Speak(); //通过父类指针去释放，不会调用子类中的析构函数，子类如果有堆区属性，会造成内存泄漏 //怎么解决？给基类增加一个虚析构函数 //虚析构函数就是用来解决通过父类指针释放子类对象 delete animal;&#125;int main() &#123; test01(); system(&quot;pause&quot;); return 0;&#125;
总结： ​ 1. 虚析构或纯虚析构就是用来解决通过父类指针释放子类对象的问题，并且纯虚析构和虚析构都需要进行声明和实现，来防止父类开辟堆区对象时的问题 ​ 2. 如果子类中没有堆区数据，可以不写为虚析构或纯虚析构 3. 拥有纯虚析构函数的类也属于抽象类
多态案例三-电脑组装案例描述： 电脑主要组成部件为 CPU（用于计算），显卡（用于显示），内存条（用于存储） 将每个零件封装出抽象基类，并且提供不同的厂商生产不同的零件，例如Intel厂商和Lenovo厂商 创建电脑类提供让电脑工作的函数，并且调用每个零件工作的接口 测试时组装三台不同的电脑进行工作 示例： #include&lt;iostream&gt;using namespace std;//抽象CPU类class CPU&#123;public: //抽象的计算函数 virtual void calculate() = 0;&#125;;//抽象显卡类class VideoCard&#123;public: //抽象的显示函数 virtual void display() = 0;&#125;;//抽象内存条类class Memory&#123;public: //抽象的存储函数 virtual void storage() = 0;&#125;;//电脑类class Computer&#123;public: Computer(CPU * cpu, VideoCard * vc, Memory * mem) &#123; m_cpu = cpu; m_vc = vc; m_mem = mem; &#125; //提供工作的函数 void work() &#123; //让零件工作起来，调用接口 m_cpu-&gt;calculate(); m_vc-&gt;display(); m_mem-&gt;storage(); &#125; //提供析构函数 释放3个电脑零件 ~Computer() &#123; //释放CPU零件 if (m_cpu != NULL) &#123; delete m_cpu; m_cpu = NULL; &#125; //释放显卡零件 if (m_vc != NULL) &#123; delete m_vc; m_vc = NULL; &#125; //释放内存条零件 if (m_mem != NULL) &#123; delete m_mem; m_mem = NULL; &#125; &#125;private: CPU * m_cpu; //CPU的零件指针 VideoCard * m_vc; //显卡零件指针 Memory * m_mem; //内存条零件指针&#125;;//具体厂商//Intel厂商class IntelCPU :public CPU&#123;public: virtual void calculate() &#123; cout &lt;&lt; &quot;Intel的CPU开始计算了！&quot; &lt;&lt; endl; &#125;&#125;;class IntelVideoCard :public VideoCard&#123;public: virtual void display() &#123; cout &lt;&lt; &quot;Intel的显卡开始显示了！&quot; &lt;&lt; endl; &#125;&#125;;class IntelMemory :public Memory&#123;public: virtual void storage() &#123; cout &lt;&lt; &quot;Intel的内存条开始存储了！&quot; &lt;&lt; endl; &#125;&#125;;void test01()&#123; //第一台电脑零件 CPU * intelCpu = new IntelCPU; VideoCard * intelCard = new IntelVideoCard; Memory * intelMem = new IntelMemory; cout &lt;&lt; &quot;第一台电脑开始工作：&quot; &lt;&lt; endl; //创建第一台电脑 Computer * computer1 = new Computer(intelCpu, intelCard, intelMem); computer1-&gt;work(); delete computer1;&#125;

&emsp; 你好，我是小八。今天我们来讲一下TCP/IP协议族。 初识TCP/IP协议族&emsp; HTTP属于TCP/IP的一个子类，通常使用的网络（包括互联网）都是在TCP/IP协议族的基础上运作。 TCP/IP协议族&emsp;计算机网络设备之间进行信息交互就需要基于相同的方法或者说是同一种协议才能进行通信。就比如：我们需要进行通信的时候，就需要知道如何探测到通信的目标、从哪一边开始发起通信请求、使用什么语言通信、怎么结束通信请求等所制定的规则，便被成为协议（protocol）。 &emsp;而TCP/IP协议族就是互联网相关的各类协议族的总称。对于TCP/IP协议族，通常有两种说法，一是指TCP和IP这两种协议，二是指TCP/IP在IP协议的通信中，使用到的协议族的统称。 TCP/IP协议族如下图：
TCP/IP的分层管理 &emsp;协议族通过分层化，可以高效管理改变不同层次设计的任务，把每个层次之间的不同接口规划好之后，每个层次的内部设计也可以自由改动，而不需要替换所有部分整体。 &emsp;应用层： &emsp;&emsp;预存各类通用的应用服务，决定了向用户提供应用服务时通信的活动。其中HTTP（超文本传输协议）、FTP（文件传输协议）、DNS（域名协议）等服务在此层 &emsp;传输层： &emsp;&emsp;对应用层提供处于网络连接中的两台计算机的数据传输。在此层中有两种不同性质的协议：TCP（传输控制协议）和UDP（用户数据报协议） &emsp;网络层： &emsp;&emsp;用来处理在网络上流动的数据包，该层规定与对方计算机进行传输时，通过选择某一种路径（或者说是某一条传输路线）到达对方计算机，并且把数据包传给对方。因此此层又被称为网络互连层。 &emsp;&emsp;数据包是网络传输的最小数据单位。 &emsp;链路层： &emsp;&emsp;用来处理连接网络的硬件部分的层次，包括控制操作系统，硬件设备驱动，NIC（网络适配器，即网卡）等一系列可见的物理传输硬件设备（媒介）。 TCP/IP通信传输流&emsp;发送端在层与层之间传输数据时，每经过一层时必定会被打上一个该层所属的首部信息。反之，接收端在层与层传输数据时，每经过一层时会把对应的首部消去。 这种把数据信息包装起来的做法称为封装（encapsulate）（就类似于C++类的使用，将类中的成员和数据进行封装）。下图为例：
&emsp;

题目如下：给你一个字符串 s，找到 s 中最长的回文子串。 如果字符串的反序与原始字符串相同，则该字符串称为回文字符串。 示例 1： 输入：s = &quot;babad&quot;输出：&quot;bab&quot;解释：&quot;aba&quot; 同样是符合题意的答案。
示例 2： 输入：s = &quot;cbbd&quot;输出：&quot;bb&quot;
提示：
1 &lt;= s.length &lt;= 1000 s 仅由数字和英文字母组成
题解如下方法一：动态规划 代码如下：class Solution &#123; public String longestPalindrome(String s) &#123; int len = s.length(); if(len &lt; 2)&#123; return s; &#125; // dp[i][j] 表示 s[i..j] 是否是回文串 boolean [][]dp = new boolean[len][len]; //所有的一个字符的子串都是回文串 for(int i = 0; i &lt; len; i++)&#123; dp[i][i] = true; &#125; char[] charArray = s.toCharArray(); //记录回文子串的初始位置 int begin = 0; //记录回文子串长度 int childLen = 1; for(int l = 2; l &lt;= len;l++)&#123; for(int i = 0;i &lt; len;i++)&#123; //j代表子串的尾字符的index，即确定右边界 int j = l + i - 1; //如果尾字符超出字符串最大长度、跳出循环 if(j &gt;= len)&#123; break; &#125; if(charArray[i]!=charArray[j])&#123; dp[i][j] = false; &#125;else&#123; if(j - i &lt; 3)&#123; //可能是一个或者两个或者三个字符的子串 dp[i][j] = true; &#125;else&#123;//否则就依次递归 dp[i][j] = dp[i + 1][j - 1]; &#125; &#125; //若 dp[i][l] == true 成立，就表示s[i....l]是回文，记录此时回文的长度以及起始位置 if(dp[i][j] &amp;&amp; j - i + 1 &gt; childLen)&#123; childLen = j - i + 1; begin = i; &#125; &#125; &#125; return s.substring(begin,begin + childLen); &#125;&#125;

这样的目的是为了后续方便说说附带的图片进行修改以及调用三方接口校验图片是否违规。
大概表设计如下：

怎么转移说说表的pics字段的****url 到新的y_talk_images字段呢？
INSERT INTO y_talk_images (talk_bid, images_url, user_bid, trace_id, is_valid, is_delete, create_time)SELECT    bid,    SUBSTRING_INDEX(SUBSTRING_INDEX(pics, &#x27;,&#x27;, numbers.n), &#x27;,&#x27;, -1) AS images_url,    y_talk.user_bid,    NULL AS trace_id,    1 AS is_valid,    0 AS is_delete,    y_talk.create_time -- 使用此图片对应的说说创建时间作为创建时间FROM    (SELECT 1 n UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4     UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8     UNION ALL SELECT 9) numbersJOIN y_talk ON CHAR_LENGTH(pics) - CHAR_LENGTH(REPLACE(pics, &#x27;,&#x27;, &#x27;&#x27;)) &gt;= numbers.n - 1WHERE    pics IS NOT NULL AND pics != &#x27;&#x27;;



CREATE TABLE y_talk_images (	id INT ( 11 ) NOT NULL AUTO_INCREMENT,	image_bid VARCHAR ( 255 ) COMMENT &#x27;图片的主键id&#x27;,	talk_bid VARCHAR ( 255 ) COMMENT &#x27;此图片对应的说说的主键id&#x27;,	images_url VARCHAR ( 1024 ) COMMENT &#x27;图片的url&#x27;,	user_bid VARCHAR ( 255 ) COMMENT &#x27;发布者的主键id&#x27;,	open_id VARCHAR ( 255 ) DEFAULT NULL COMMENT &#x27;微信id&#x27;,	trace_id VARCHAR ( 50 ) COMMENT &#x27;每张照片微信接口校验时返回的任务id&#x27;,	is_valid INT ( 1 ) NOT NULL DEFAULT 0 COMMENT &#x27;是否通过校验，0待审核，1审核通过，2审核不通过&#x27;,	is_delete INT ( 1 ) NOT NULL DEFAULT 0 COMMENT &#x27;图片url是否被软删除&#x27;,	create_time datetime DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY ( `id` ) USING BTREE );

题目描述：给你链表的头节点 head ，每 k 个节点一组进行翻转，请你返回修改后的链表。 k 是一个正整数，它的值小于或等于链表的长度。如果节点总数不是 k 的整数倍，那么请将最后剩余的节点保持原有顺序。 你不能只是单纯的改变节点内部的值，而是需要实际进行节点交换。
输入：head = [1,2,3,4,5], k = 2输出：[2,1,4,3,5]
输入：head = [1,2,3,4,5], k = 3输出：[3,2,1,4,5]
思路关键点： 局部翻转 k &gt; 剩余局部链表长度时，这部分链表无需翻转
步骤： 初始化 ListNode dummy = new ListNode(0,head);
设置指针实现局部翻转 ListNode pre = dummy,end = dummy
end.next != null 则遍历链表
根据k确定第一组局部链表的尾部指针 for(int i = 0; i &lt; k &amp;&amp; end != null; i++) end = end.next; 此时end == null时，说明剩余的局部链表长度小于k，直接跳出循环无需翻转链表。
确定局部链表起始位置及下一组的起始位置 start = pre.next;next = end.next; 断开end的后续链表，并调用翻转函数使pre.next连接翻转后的链表。 pre.next = reverse(start);
重新连接被翻转和未翻转的部分 start.next = next;//连接后面未翻转的链表pre = next;//重置pre和end指针开始新的一轮链表组的翻转end = pre;
返回dummy后面所有已经翻转的链表
关键代码class Solution &#123; public ListNode reverseKGroup(ListNode head, int k) &#123; ListNode dummy = new ListNode(0, head); ListNode pre = dummy, end = dummy; while(end.next != null)&#123; for(int i = 0; i &lt; k &amp;&amp; end != null; i++)&#123; end = end.next; &#125; if(end == null) break; ListNode start = pre.next; ListNode next = end.next; end.next = null; pre.next = reverse(start); start.next = next; pre = start; end = pre; &#125; return dummy.next; &#125; public ListNode reverse(ListNode head)&#123; ListNode pre = null; ListNode cur = head; while(cur != null)&#123; ListNode next = cur.next; cur.next = pre; pre = cur; cur = next; &#125; return pre; &#125;&#125;

​ AOP（面向切面编程）：就是把公共逻辑抽出来，让开发者更好的专注于业务逻辑的开发，AOP是OOP的补充，OOP是面向类和对象的，但是AOP是面向不同切面的，一个切面可以横跨多个类和对象去操作，极大提高开发效率。 ​ 例如一个订单的创建，可能需要下列四个步骤 ​ 1、权限校验 ​ 2、事务管理 ​ 3、创建订单 ​ 4、日志打印 ​ 如果使用AOP的思想，其实就可以把四个步骤抽象成四个切面，让开发者专注于第3个切面，其他的切面都用基础通用的逻辑（就是抽象出来的公共逻辑），统计交给AOP封装管理。 实现原理：通过代理模式实现，实现方式有两种，一种事基于Java原生的动态代理，一种是基于cglib的动态代理。 Spring AOP默认使用JDK的原生代理，可以代理任何接口，但是不能代理没有接口的类，所以使用cglib来实现动态代理没有接口的类。 AOP的业务场景：1、参数校验 当使用AOP思想实现参数校验功能时，你可以创建一个AOP切面来拦截需要校验的方法，并从HttpServletRequest中获取JWT参数进行校验。以下是一个基本示例：
创建自定义注解： 创建一个自定义注解，用于标记需要进行JWT校验的方法。
import java.lang.annotation.ElementType;import java.lang.annotation.Retention;import java.lang.annotation.RetentionPolicy;import java.lang.annotation.Target;@Retention(RetentionPolicy.RUNTIME)@Target(ElementType.METHOD)public @interface ValidateJWT &#123;&#125;
编写AOP切面： 创建一个AOP切面，用于拦截带有@ValidateJWT注解的方法，并从HttpServletRequest中获取JWT参数进行校验。
import javax.servlet.http.HttpServletRequest;import org.aspectj.lang.JoinPoint;import org.aspectj.lang.annotation.Aspect;import org.aspectj.lang.annotation.Before;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Component;@Aspect@Componentpublic class JWTValidationAspect &#123; @Autowired private HttpServletRequest request; // 替换为你的JWT密钥 private final String secretKey = &quot;your-secret-key&quot;; @Before(&quot;@annotation(com.example.ValidateJWT)&quot;) public void validateJWT(JoinPoint joinPoint) &#123; String jwtToken = extractTokenFromRequest(request); if (jwtToken == null) &#123; throw new IllegalArgumentException(&quot;JWT token is missing&quot;); &#125; try &#123; Claims claims = Jwts.parser().setSigningKey(secretKey).parseClaimsJws(jwtToken).getBody(); // 在这里可以根据需要进一步处理claims，比如判断过期时间、验证issuer等 &#125; catch (Exception e) &#123; throw new IllegalArgumentException(&quot;Invalid JWT token&quot;); &#125; &#125; private String extractTokenFromRequest(HttpServletRequest request) &#123; String authorizationHeader = request.getHeader(&quot;Authorization&quot;); if (authorizationHeader != null &amp;&amp; authorizationHeader.startsWith(&quot;Bearer &quot;)) &#123; return authorizationHeader.substring(7); &#125; return null; &#125;&#125;
在这个示例中，我们使用了@Autowired来注入HttpServletRequest，然后在AOP切面中使用extractTokenFromRequest方法从请求头中提取JWT token。然后，我们在校验逻辑中解析JWT token，并根据需要处理JWT的内容。这个切面会在带有@ValidateJWT注解的方法执行前进行JWT校验。
在需要校验的方法上添加注解： 在需要校验JWT的方法上添加@ValidateJWT注解。
import org.springframework.stereotype.Service;@Servicepublic class YourService &#123; @ValidateJWT public void processRequest() &#123; // 在这里处理请求，前置通知会在此方法执行前进行JWT校验 &#125;&#125;
这个示例中，processRequest方法会在执行前进行JWT校验，确保JWT的有效性。同时，你可以将类似的校验逻辑应用于其他带有JWT的方法，以提高代码的安全性和可维护性。请注意，实际项目中可能需要根据业务需求进行更复杂的校验逻辑。 2、缓存逻辑 当使用AOP思想来实现Redis的缓存逻辑时，你可以按照以下步骤来操作：
引入依赖： 在你的项目中引入Spring Data Redis依赖，确保你能够使用Redis作为缓存。
创建缓存切面： 创建一个AOP切面，用于拦截带有@CacheableResult注解的方法，并将方法的返回值缓存到Redis。
import org.aspectj.lang.JoinPoint;import org.aspectj.lang.annotation.AfterReturning;import org.aspectj.lang.annotation.Aspect;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.data.redis.core.RedisTemplate;import org.springframework.stereotype.Component;@Aspect@Componentpublic class CacheAspect &#123; @Autowired private RedisTemplate&lt;String, Object&gt; redisTemplate; @AfterReturning(pointcut = &quot;@annotation(com.example.CacheableResult)&quot;, returning = &quot;result&quot;) public void cacheMethodResult(JoinPoint joinPoint, Object result) &#123; String methodName = joinPoint.getSignature().toShortString(); redisTemplate.opsForValue().set(methodName, result); &#125;&#125;
在这个切面中，我们使用了@Autowired注入了RedisTemplate，这是Spring提供的与Redis交互的工具类。cacheMethodResult方法会在带有@CacheableResult注解的方法执行后执行，将方法返回的结果存储到Redis缓存中，使用方法的名称作为缓存的键。
创建自定义注解： 创建一个自定义注解，用于标记需要进行缓存的方法。
import java.lang.annotation.ElementType;import java.lang.annotation.Retention;import java.lang.annotation.RetentionPolicy;import java.lang.annotation.Target;@Retention(RetentionPolicy.RUNTIME)@Target(ElementType.METHOD)public @interface CacheableResult &#123;&#125;
在需要缓存的方法上添加注解： 在需要进行缓存的方法上添加@CacheableResult注解。
import org.springframework.stereotype.Service;@Servicepublic class YourService &#123; @CacheableResult public String getFromDatabase() &#123; // 这里可以模拟从数据库中获取数据的操作 return &quot;Data from database&quot;; &#125;&#125;
在这个示例中，getFromDatabase方法被@CacheableResult注解标记，当这个方法被调用并返回结果时，切面会拦截这个方法的执行，将返回的数据存储到Redis缓存中。
启用AOP和组件扫描： 在Spring Boot的配置类上添加@EnableAspectJAutoProxy注解，以启用AOP功能，同时确保你的切面和服务类被正确地扫描到。
import org.springframework.context.annotation.ComponentScan;import org.springframework.context.annotation.Configuration;import org.springframework.context.annotation.EnableAspectJAutoProxy;@Configuration@EnableAspectJAutoProxy@ComponentScan(basePackages = &quot;com.example&quot;)public class AppConfig &#123; // 配置其他内容&#125;
通过以上步骤，你就可以使用AOP思想实现基本的Redis缓存逻辑。当使用带有@CacheableResult注解的方法时，切面会自动将方法的结果存储到Redis缓存中。在实际项目中，你可能还需要考虑缓存的失效策略、数据更新时的缓存更新等细节。同时，Spring框架也提供了更丰富的缓存管理功能，你可以根据具体的需求进行选择和配置。 3、日志打印 实际上在日志打印的场景中，不一定需要创建自定义注解。通常情况下，日志打印是一种通用的操作，因此你可以直接在切面中定义切点，而不必引入自定义注解。 以下是一个更准确的示例，展示如何使用AOP来实现日志打印功能：
创建日志切面： 创建一个AOP切面，用于拦截方法的执行并记录日志。
import org.aspectj.lang.JoinPoint;import org.aspectj.lang.annotation.AfterReturning;import org.aspectj.lang.annotation.Aspect;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.stereotype.Component;@Aspect@Componentpublic class LoggingAspect &#123; private final Logger logger = LoggerFactory.getLogger(LoggingAspect.class); @AfterReturning(&quot;execution(* com.example.*.*(..))&quot;) public void logMethodExecution(JoinPoint joinPoint) &#123; String methodName = joinPoint.getSignature().toShortString(); logger.info(&quot;Method &#123;&#125; executed&quot;, methodName); &#125;&#125;
在这个切面中，LoggingAspect会拦截com.example包下所有方法的执行，在方法执行后使用logger记录方法的名称。
启用AOP和组件扫描： 在Spring Boot的配置类上添加@EnableAspectJAutoProxy注解，以启用AOP功能，同时确保你的切面被正确地扫描到。
import org.springframework.context.annotation.ComponentScan;import org.springframework.context.annotation.Configuration;import org.springframework.context.annotation.EnableAspectJAutoProxy;@Configuration@EnableAspectJAutoProxy@ComponentScan(basePackages = &quot;com.example&quot;)public class AppConfig &#123; // 配置其他内容&#125;
确保basePackages中的包路径是你的切面和服务类所在的包。
调用方法： 在业务逻辑中调用方法，切面会在方法执行后记录日志。
import org.springframework.stereotype.Service;@Servicepublic class YourService &#123; public String process() &#123; // 业务逻辑 return &quot;Processed result&quot;; &#125;&#125;
在这个示例中，当调用process方法时，切面会在方法执行后使用日志记录相关信息。
配置日志输出： 在src/main/resources目录下创建logback.xml文件，根据你的需求配置日志的输出格式、级别等。
&lt;configuration&gt; &lt;appender name=&quot;CONSOLE&quot; class=&quot;ch.qos.logback.core.ConsoleAppender&quot;&gt; &lt;encoder&gt; &lt;pattern&gt;%d&#123;HH:mm:ss.SSS&#125; [%thread] %-5level %logger&#123;36&#125; - %msg%n&lt;/pattern&gt; &lt;/encoder&gt; &lt;/appender&gt; &lt;root level=&quot;INFO&quot;&gt; &lt;appender-ref ref=&quot;CONSOLE&quot;/&gt; &lt;/root&gt;&lt;/configuration&gt;
通过以上步骤，你就可以使用AOP思想实现基本的日志打印功能。当执行方法时，切面会在方法执行后记录相关的日志信息。

什么是IOC所谓的IOC就是Inversion Of Control，也就是控制反转，其实就是对于某个对象A，原来的控制权在B手上，B想用就能用，想不用就不用，但是现在把控制权交还给了A，只有A给了别人权限才能用，这就是控制反转。
没有IOC的时候，举例如下：
class A&#123;&#125;class B&#123;    private A a = new A();//此时就是我们所说的控制权在B手上，也就是控制(不是控制反转)    public void use()&#123;        System.out.println(a);//此时B对A控制使用    &#125;&#125;

有了IOC时使用如下：
@Component class A&#123;&#125;class B&#123;    //此时控制权在A自己手上，可以直接使用，当然如果对象A没有注入到容器之中的话，B就不能使用。    @Resource    private A a;        private void use()&#123;        System.out.println(a);//此时B对A控制使用    &#125;&#125;

总结下来就是：IOC（不是指的Spring IOC容器，Spring IOC容器是实现IOC思想的一个载体）实际上就是一种设计思想，可以通过Spring框架对一些原本本来需要手动创建的对象，交由Spring框架统一管理。
​    如果没有Spring的IOC容器的话，我们要使用某个对象的时候只能通过创建对象的方式解决，但是有了SpringIOC容器之后，对象就会交由IOC容器创建并管理，当我们想使用的时候就直接从容器中获取即可。

业务场景：热点动态中的某一条说说因为过期且当时大量用户请求查看动态详情，出现数据库查询压力骤增的情况，从而导致某一热点动态的缓存击穿的情况。 想法：1、 互斥锁：在热点数据的缓存失效时，可以尝试使用分布式锁来避免多个请求同时访问数据库。在获取锁的情况下，只有一个请求去加载数据并更新缓存，其他请求等待，从而减轻数据库的压力。
获取互斥锁： 当缓存失效时，多个请求会尝试获取一个互斥锁。如果只有一个请求能够成功获取锁，那么它将负责加载数据并更新缓存。 获取锁成功： 如果某个请求成功获取了互斥锁，它可以开始加载数据。在加载数据时，需要判断缓存是否已经被其他请求加载（可能在当前请求获取锁的过程中被其他请求加载了），避免重复加载数据。 更新缓存： 获取锁成功的请求负责加载数据并更新缓存。在更新缓存之后，释放互斥锁，让其他等待锁的请求有机会获取锁并使用更新后的缓存。 获取锁失败： 如果请求获取锁失败，意味着其他请求已经在加载数据和更新缓存了。这些失败的请求可以等待一段时间后再次尝试，或者直接返回默认值，以避免多次同时访问数据库。
伪代码如下：import org.springframework.data.redis.core.RedisTemplate;import java.util.concurrent.TimeUnit;import java.util.function.Supplier;public class CacheWithMutexLock&lt;T&gt; &#123; private final RedisTemplate&lt;String, T&gt; redisTemplate; private static final String LOCK_PREFIX = &quot;lock_&quot;; public CacheWithMutexLock(RedisTemplate&lt;String, T&gt; redisTemplate) &#123; this.redisTemplate = redisTemplate; &#125; public T getOrLoadFromCache(String key, Supplier&lt;T&gt; dataLoader, T defaultValue, long lockTimeout) &#123; String lockKey = LOCK_PREFIX + key; try &#123; // 尝试获取互斥锁 boolean gotLock = redisTemplate.opsForValue().setIfAbsent(lockKey, &quot;locked&quot;, lockTimeout, TimeUnit.MILLISECONDS); if (gotLock) &#123; try &#123; // 检查缓存是否已经加载 T cachedValue = redisTemplate.opsForValue().get(key); if (cachedValue != null) &#123; return cachedValue; &#125; // 加载数据并更新缓存 T loadedValue = dataLoader.get(); redisTemplate.opsForValue().set(key, loadedValue); return loadedValue; &#125; finally &#123; // 释放锁 redisTemplate.delete(lockKey); &#125; &#125; else &#123; // 获取锁失败，返回默认值 return defaultValue; &#125; &#125; catch (Exception e) &#123; e.printStackTrace(); return defaultValue; &#125; &#125;&#125;
getOrLoadFromCache 方法尝试获取互斥锁，如果获取成功，它会检查缓存是否已经加载数据，如果没有则加载数据并更新缓存。如果获取锁失败，就直接返回默认值。 RedisTemplate&lt;String, String&gt; redisTemplate = ...; // 初始化 RedisTemplateCacheWithMutexLock&lt;String&gt; cache = new CacheWithMutexLock&lt;&gt;(redisTemplate);String key = &quot;my_key&quot;;String result = cache.getOrLoadFromCache(key, () -&gt; &#123; // 从数据库或其他数据源加载数据的逻辑 return &quot;Loaded data&quot;; &#125;, &quot;Default value&quot;, 5000 // 互斥锁的超时时间，单位为毫秒);
RedisTemplate 的一个简化实现。使用互斥锁来协调多个请求的数据加载和缓存更新，可以避免缓存击穿问题。

Spring容器启动public static void main(String[] args) &#123;    ApplicationContext context = new ClassPathXmlApplicationContext(&quot;classpath:applicationfile.xml&quot;);&#125;

ApplicationContext context = new ClassPathXmlApplicationContext(...)就是在 ClassPath 中寻找 xml 配置文件，根据 xml 文件内容来构建 ApplicationContext。

简单介绍一下FileSystemXmlApplicationContext 和 AnnotationConfigApplicationContext 这两个类
1、FileSystemXmlApplicationContext 的构造函数需要一个 xml 配置文件在系统中的路径，其他和 ClassPathXmlApplicationContext 基本上一样。
2、AnnotationConfigApplicationContext 是基于注解来使用的，它不需要配置文件，采用 java 配置类和各种注解来配置，是比较简单的方式。
利用ClassPathXmlApplicationContext类创建一个实例：
首先，定义一个接口：
public interface MessageService &#123;    String getMessage();&#125;

定义接口实现类：
public class MessageServiceImpl implements MessageService &#123;    public String getMessage() &#123;        return &quot;hello world&quot;;    &#125;&#125;

接下来，我们在 resources 目录新建一个配置文件，文件名随意，通常叫 application.xml 或 application-xxx.xml 就可以了：
&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot; ?&gt;&lt;beans xmlns:xsi=&quot;http://www.w3.org/2001/XMLSchema-instance&quot;       xmlns=&quot;http://www.springframework.org/schema/beans&quot;       xsi:schemaLocation=&quot;http://www.springframework.org/schema/beans http://www.springframework.org/schema/beans/spring-beans.xsd&quot; default-autowire=&quot;byName&quot;&gt;    &lt;bean id=&quot;messageService&quot; class=&quot;com.javadoop.example.MessageServiceImpl&quot;/&gt;&lt;/beans&gt;

这样，我们就可以跑起来了：
public class App &#123;    public static void main(String[] args) &#123;        // 用我们的配置文件来启动一个 ApplicationContext        ApplicationContext context = new ClassPathXmlApplicationContext(&quot;classpath:application.xml&quot;);        System.out.println(&quot;context 启动成功&quot;);        // 从 context 中取出我们的 Bean，而不是用 new MessageServiceImpl() 这种方式        MessageService messageService = context.getBean(MessageService.class);        // 这句将输出: hello world        System.out.println(messageService.getMessage());    &#125;&#125;

BeanFactory顾名思义，就是一个生产Bean的工厂，负责生产和管理各个Bean实例，刚刚所说的ApplicationContext 实际上就是一个BeanFactory，BeanFactory接口继承结构如下：


ListableBeanFactory：根据句Listable可知通过这个接口我们可以获取多个Bean，但是顶层BeanFactory只能每次获取单个Bean实例

HierarchicalBeanFactory：通过Hierarchical这个单词可知，我们可以通过这个接口创建多个BeanFactory（不是多个Bean实例），然后将多个BeanFactory设置为父子关系。

AutowireCapableBeanFactory 用于自动装配Bean的，虽然ApplicationContext 没有继承它，但是可以使用组合，ApplicationContext 的最后一个方法getAutowireCapableBeanFactory()就是组合使用。


public interface ApplicationContext extends EnvironmentCapable, ListableBeanFactory, HierarchicalBeanFactory, MessageSource, ApplicationEventPublisher, ResourcePatternResolver &#123;    String getId();    String getApplicationName();    String getDisplayName();    long getStartupDate();    ApplicationContext getParent();    AutowireCapableBeanFactory getAutowireCapableBeanFactory() throws IllegalStateException;&#125;


ConfigurableListableBeanFactory 这个接口比较特殊，继承了第二层的所有三个接口，但是ApplicationContext 没有

启动过程分析ClassPathXmlApplicationContextpublic class ClassPathXmlApplicationContext extends AbstractXmlApplicationContext &#123;  private Resource[] configResources;  // 如果已经有 ApplicationContext 并需要配置成父子关系，那么调用这个构造方法  public ClassPathXmlApplicationContext(ApplicationContext parent) &#123;    super(parent);  &#125;  ...  public ClassPathXmlApplicationContext(String[] configLocations, boolean refresh, ApplicationContext parent)      throws BeansException &#123;    super(parent);    // 根据提供的路径，处理成配置文件数组(以分号、逗号、空格、tab、换行符分割)    setConfigLocations(configLocations);    if (refresh) &#123;      refresh(); // 核心方法    &#125;  &#125;    ...&#125;

refresh()方法介绍一下refresh方法，因为他是ClassPathXmlApplicationContext类构造方法的核心方法，它主要的作用就是用于重建，refresh方法会将原来的ApplicationContext销毁然后重新执行一次初始化操作。源码如下：
@Overridepublic void refresh() throws BeansException, IllegalStateException &#123;   // 这里创建一个锁，不然 refresh() 还没结束，你又来个启动或销毁容器的操作，那不就乱套了嘛，类似于MySQL“当前读”防止幻读的时候的间隙锁。   synchronized (this.startupShutdownMonitor) &#123;      // 准备工作，记录下容器的启动时间、标记“已启动”状态、处理配置文件中的占位符      prepareRefresh();      // 这步比较关键，这步完成后，配置文件就会解析成一个个 Bean 定义，注册到 BeanFactory 中，      // 当然，这里说的 Bean 还没有初始化，只是配置信息都提取出来了，      // 注册也只是将这些信息都保存到了注册中心(说到底核心是一个 beanName-&gt; beanDefinition 的 map)      ConfigurableListableBeanFactory beanFactory = obtainFreshBeanFactory();             // 设置 BeanFactory 的类加载器，添加几个 BeanPostProcessor，手动注册几个特殊的 bean      // 这块待会会展开说      prepareBeanFactory(beanFactory);      try &#123;         // 【这里需要知道 BeanFactoryPostProcessor 这个知识点，Bean 如果实现了此接口，         // 那么在容器初始化以后，Spring 会负责调用里面的 postProcessBeanFactory 方法。】         // 这里是提供给子类的扩展点，到这里的时候，所有的 Bean 都加载、注册完成了，但是都还没有初始化         // 具体的子类可以在这步的时候添加一些特殊的 BeanFactoryPostProcessor 的实现类或做点什么事         postProcessBeanFactory(beanFactory);         // 调用 BeanFactoryPostProcessor 各个实现类的 postProcessBeanFactory(factory) 方法         invokeBeanFactoryPostProcessors(beanFactory);         // 注册 BeanPostProcessor 的实现类，注意看和 BeanFactoryPostProcessor 的区别         // 此接口两个方法: postProcessBeforeInitialization 和 postProcessAfterInitialization         // 两个方法分别在 Bean 初始化之前和初始化之后得到执行。注意，到这里 Bean 还没初始化         registerBeanPostProcessors(beanFactory);         // 初始化当前 ApplicationContext 的 MessageSource。         initMessageSource();         // 初始化当前 ApplicationContext 的事件广播器。         initApplicationEventMulticaster();          // 从方法名就可以知道，典型的模板方法(钩子方法)，         // 具体的子类可以在这里初始化一些特殊的 Bean（在初始化 singleton beans 之前）         onRefresh();         // 注册事件监听器，监听器需要实现 ApplicationListener 接口。这也不是我们的重点，过         registerListeners();         // 重点，重点，重点         // 初始化所有的 singleton beans         //（lazy-init 的除外）         finishBeanFactoryInitialization(beanFactory);         // 最后，广播事件，ApplicationContext 初始化完成         finishRefresh();      &#125;      catch (BeansException ex) &#123;         if (logger.isWarnEnabled()) &#123;            logger.warn(&quot;Exception encountered during context initialization - &quot; +                  &quot;cancelling refresh attempt: &quot; + ex);         &#125;         // Destroy already created singletons to avoid dangling resources.         // 销毁已经初始化的 singleton 的 Beans，以免有些 bean 会一直占用资源         destroyBeans();         // Reset &#x27;active&#x27; flag.         cancelRefresh(ex);         // 把异常往外抛         throw ex;      &#125;      finally &#123;         // Reset common introspection caches in Spring&#x27;s core, since we         // might not ever need metadata for singleton beans anymore...         resetCommonCaches();      &#125;   &#125;&#125;

创建 Bean 容器前的准备工作prepareRefresh()就是用来创建Bean容器之前的准备工作，在讲refresh方法中讲到过，主要是记录下容器的启动时间、标记“已启动”状态、处理配置文件中的占位符。
protected void prepareRefresh() &#123;   // 记录启动时间，   // 将 active 属性设置为 true，closed 属性设置为 false，它们都是 AtomicBoolean 类型   this.startupDate = System.currentTimeMillis();   this.closed.set(false);   this.active.set(true);   if (logger.isInfoEnabled()) &#123;      logger.info(&quot;Refreshing &quot; + this);   &#125;   // Initialize any placeholder property sources in the context environment，初始化上下文环境中的任何占位符属性源   initPropertySources();   // 校验 xml 配置文件   getEnvironment().validateRequiredProperties();   this.earlyApplicationEvents = new LinkedHashSet&lt;ApplicationEvent&gt;();&#125;

创建Bean容器，加载并注册BeanobtainFreshBeanFactory() 方法就是用于初始化BeanFactory、加载Bean、注册Bean等这个方法是refresh中最重要的一个部分，但是这个方法执行结束之后Bean实例并没有生成，也就是说Bean没有完成初始化。
protected ConfigurableListableBeanFactory obtainFreshBeanFactory() &#123;   // 关闭旧的 BeanFactory (如果有)，创建新的 BeanFactory，加载 Bean 定义、注册 Bean 等等   refreshBeanFactory();   // 返回刚刚创建的 BeanFactory   ConfigurableListableBeanFactory beanFactory = getBeanFactory();   if (logger.isDebugEnabled()) &#123;      logger.debug(&quot;Bean factory for &quot; + getDisplayName() + &quot;: &quot; + beanFactory);   &#125;   return beanFactory;&#125;

@Overrideprotected final void refreshBeanFactory() throws BeansException &#123;   // 如果 ApplicationContext 中已经加载过 BeanFactory 了，销毁所有 Bean，关闭 BeanFactory   // 注意，应用中 BeanFactory 本来就是可以多个的，这里可不是说应用全局是否有 BeanFactory，而是当前ApplicationContext 是否有 BeanFactory   if (hasBeanFactory()) &#123;      destroyBeans();      closeBeanFactory();   &#125;   try &#123;      // 初始化一个 DefaultListableBeanFactory，至于为什么要用这个类是因为前面说的继承图，具体为什么见下方注解      DefaultListableBeanFactory beanFactory = createBeanFactory();      // 用于 BeanFactory 的序列化      beanFactory.setSerializationId(getId());             // 设置 BeanFactory 的两个配置属性：是否允许 Bean 覆盖、是否允许循环引用      customizeBeanFactory(beanFactory);      // 加载 Bean 到 BeanFactory 中      loadBeanDefinitions(beanFactory);      synchronized (this.beanFactoryMonitor) &#123;         this.beanFactory = beanFactory;      &#125;   &#125;   catch (IOException ex) &#123;      throw new ApplicationContextException(&quot;I/O error parsing bean definition source for &quot; + getDisplayName(), ex);   &#125;&#125;


为什么选择实例化 DefaultListableBeanFactory ？
前面的BeanFactory中有一个接口叫做ConfigurableListableBeanFactory，它实现了BeanFactory下面一层的所有三个接口，而这个接口只有一个实现类DefaultListableBeanFactory，而实现类DefaultListableBeanFactory实际上间接实现了BeanFactory下的三个接口，所以结论就是，DefaultListableBeanFactory是最牛的BeanFactory。例图如下


customizeBeanFactory(beanFactory)方法就是配置是否允许BeanDefinition覆盖、是否允许循环引用。
protected void customizeBeanFactory(DefaultListableBeanFactory beanFactory) &#123;   if (this.allowBeanDefinitionOverriding != null) &#123;      // 是否允许 Bean 定义覆盖      beanFactory.setAllowBeanDefinitionOverriding(this.allowBeanDefinitionOverriding);   &#125;   if (this.allowCircularReferences != null) &#123;      // 是否允许 Bean 间的循环依赖      beanFactory.setAllowCircularReferences(this.allowCircularReferences);   &#125;&#125;

loadBeanDefinitions(beanFactory)就是根据配置，加载各个Bean，然后放到BeanFactory中
protected void loadBeanDefinitions(DefaultListableBeanFactory beanFactory) throws BeansException, IOException &#123;   // 给这个 BeanFactory 实例化一个 XmlBeanDefinitionReader来读取加载配置、解析   XmlBeanDefinitionReader beanDefinitionReader = new XmlBeanDefinitionReader(beanFactory);   // Configure the bean definition reader with this context&#x27;s   // resource loading environment.   beanDefinitionReader.setEnvironment(this.getEnvironment());   beanDefinitionReader.setResourceLoader(this);   beanDefinitionReader.setEntityResolver(new ResourceEntityResolver(this));   // 初始化 BeanDefinitionReader，其实这个是提供给子类覆写的，   initBeanDefinitionReader(beanDefinitionReader);           // 重点来了，继续往下，实际上就是loadBeanDefinitions()方法的重载，这两个方法还是在一个类中   loadBeanDefinitions(beanDefinitionReader);&#125;protected void loadBeanDefinitions(XmlBeanDefinitionReader reader) throws BeansException, IOException &#123;   Resource[] configResources = getConfigResources();   if (configResources != null) &#123;      // 往下看      reader.loadBeanDefinitions(configResources);   &#125;   String[] configLocations = getConfigLocations();   if (configLocations != null) &#123;      // 2      reader.loadBeanDefinitions(configLocations);   &#125;&#125;public int loadBeanDefinitions(Resource... resources) throws BeanDefinitionStoreException &#123;   Assert.notNull(resources, &quot;Resource array must not be null&quot;);   int counter = 0;   // 注意这里是个 for 循环，也就是每个文件是一个 resource   for (Resource resource : resources) &#123;      // 继续往下看      counter += loadBeanDefinitions(resource);   &#125;   // 最后返回 counter，表示总共加载了多少的 BeanDefinition   return counter;&#125;public int loadBeanDefinitions(Resource resource) throws BeanDefinitionStoreException &#123;   return loadBeanDefinitions(new EncodedResource(resource));&#125;public int loadBeanDefinitions(EncodedResource encodedResource) throws BeanDefinitionStoreException &#123;   Assert.notNull(encodedResource, &quot;EncodedResource must not be null&quot;);   if (logger.isInfoEnabled()) &#123;      logger.info(&quot;Loading XML bean definitions from &quot; + encodedResource.getResource());   &#125;   // 用一个 ThreadLocal 来存放配置文件资源   Set&lt;EncodedResource&gt; currentResources = this.resourcesCurrentlyBeingLoaded.get();   if (currentResources == null) &#123;      currentResources = new HashSet&lt;EncodedResource&gt;(4);      this.resourcesCurrentlyBeingLoaded.set(currentResources);   &#125;   if (!currentResources.add(encodedResource)) &#123;      throw new BeanDefinitionStoreException(            &quot;Detected cyclic loading of &quot; + encodedResource + &quot; - check your import definitions!&quot;);   &#125;   try &#123;      InputStream inputStream = encodedResource.getResource().getInputStream();      try &#123;         InputSource inputSource = new InputSource(inputStream);         if (encodedResource.getEncoding() != null) &#123;            inputSource.setEncoding(encodedResource.getEncoding());         &#125;         // 核心部分是这里，往下面看         return doLoadBeanDefinitions(inputSource, encodedResource.getResource());      &#125;      finally &#123;         inputStream.close();      &#125;   &#125;   catch (IOException ex) &#123;      throw new BeanDefinitionStoreException(            &quot;IOException parsing XML document from &quot; + encodedResource.getResource(), ex);   &#125;   finally &#123;      currentResources.remove(encodedResource);      if (currentResources.isEmpty()) &#123;         this.resourcesCurrentlyBeingLoaded.remove();      &#125;   &#125;&#125;protected int doLoadBeanDefinitions(InputSource inputSource, Resource resource)      throws BeanDefinitionStoreException &#123;   try &#123;      // 这里就不看了，将 xml 文件转换为 Document 对象      Document doc = doLoadDocument(inputSource, resource);      // 继续      return registerBeanDefinitions(doc, resource);   &#125;   catch (...&#125;          // 返回值：返回从当前配置文件加载了多少数量的 Beanpublic int registerBeanDefinitions(Document doc, Resource resource) throws BeanDefinitionStoreException &#123;   BeanDefinitionDocumentReader documentReader = createBeanDefinitionDocumentReader();   int countBefore = getRegistry().getBeanDefinitionCount();       // 这里才使用另外一个类(DefaultBeanDefinitionDocumentReader)的方法   documentReader.registerBeanDefinitions(doc, createReaderContext(resource));   return getRegistry().getBeanDefinitionCount() - countBefore;&#125;          //创建DOM树结构，其中的doRegisterBeanDefinitions()函数主要用于解析xml文件@Overridepublic void registerBeanDefinitions(Document doc, XmlReaderContext readerContext) &#123;   this.readerContext = readerContext;   logger.debug(&quot;Loading bean definitions&quot;);   Element root = doc.getDocumentElement();   // 从 xml 根节点开始解析文件   doRegisterBeanDefinitions(root);&#125;

初级篇：1-341. 左大括号 &#123; 不能单独放一行在其他大多数语言中，&#123; 的位置你自行决定。Go 比较特别，遵守分号注入规则（automatic semicolon injection）：编译器会在每行代码尾部特定分隔符后加 ; 来分隔多条语句，比如会在 ) 后加分号：
// 错误示例func main()&#123;    println(&quot;hello world&quot;)&#125;// 等效于func main();    // 无函数体&#123;    println(&quot;hello world&quot;)&#125;


./main.go: missing function body


./main.go: syntax error: unexpected semicolon or newline before {

// 正确示例func main() &#123;    println(&quot;hello world&quot;)&#125;

2. 未使用的变量如果在函数体代码中有未使用的变量，则无法通过编译，不过全局变量声明但不使用是可以的。
即使变量声明后为变量赋值，依旧无法通过编译，需在某处使用它：
// 错误示例var gvar int     // 全局变量，声明不使用也可以func main() &#123;    var one int     // error: one declared and not used    two := 2    // error: two declared and not used    var three int    // error: three declared and not used    three = 3&#125;// 正确示例// 可以直接注释或移除未使用的变量func main() &#123;    var one int    _ = one    two := 2    println(two)    var three int    one = three    var four int    four = four&#125;

3. 未使用的 import如果你 import 一个包，但包中的变量、函数、接口和结构体一个都没有用到的话，将编译失败。
可以使用 _ 下划线符号作为别名来忽略导入的包，从而避免编译错误，这只会执行 package 的 init()
// 错误示例import (    &quot;fmt&quot;    // imported and not used: &quot;fmt&quot;    &quot;log&quot;    // imported and not used: &quot;log&quot;    &quot;time&quot;    // imported and not used: &quot;time&quot;)func main() &#123;&#125;// 正确示例// 可以使用 goimports 工具来注释或移除未使用到的包import (    _ &quot;fmt&quot;    &quot;log&quot;    &quot;time&quot;)func main() &#123;    _ = log.Println    _ = time.Now&#125;

4. 简短声明的变量只能在函数内部使用// 错误示例myvar := 1    // syntax error: non-declaration statement outside function bodyfunc main() &#123;&#125;// 正确示例var  myvar = 1func main() &#123;&#125;

5. 使用简短声明来重复声明变量不能用简短声明方式来单独为一个变量重复声明， := 左侧至少有一个新变量，才允许多变量的重复声明：
// 错误示例func main() &#123;    one := 0    one := 1 // error: no new variables on left side of :=&#125;// 正确示例func main() &#123;    one := 0    one, two := 1, 2    // two 是新变量，允许 one 的重复声明。比如 error 处理经常用同名变量 err    one, two = two, one    // 交换两个变量值的简写&#125;

6. 不能使用简短声明来设置字段的值struct 的变量字段不能使用 := 来赋值以使用预定义的变量来避免解决：
// 错误示例type info struct &#123;    result int&#125;func work() (int, error) &#123;    return 3, nil&#125;func main() &#123;    var data info    data.result, err := work()    // error: non-name data.result on left side of :=    fmt.Printf(&quot;info: %+v\n&quot;, data)&#125;// 正确示例func main() &#123;    var data info    var err error    // err 需要预声明    data.result, err = work()    if err != nil &#123;        fmt.Println(err)        return    &#125;    fmt.Printf(&quot;info: %+v\n&quot;, data)&#125;

7. 不小心覆盖了变量对从动态语言转过来的开发者来说，简短声明很好用，这可能会让人误会 := 是一个赋值操作符。
如果你在新的代码块中像下边这样误用了 :=，编译不会报错，但是变量不会按你的预期工作：
func main() &#123;    x := 1    println(x)        // 1    &#123;        println(x)    // 1        x := 2        println(x)    // 2    // 新的 x 变量的作用域只在代码块内部    &#125;    println(x)        // 1&#125;

这是 Go 开发者常犯的错，而且不易被发现。
可使用 vet 工具来诊断这种变量覆盖，Go 默认不做覆盖检查，添加 -shadow 选项来启用：
&gt; go tool vet -shadow main.gomain.go:9: declaration of &quot;x&quot; shadows declaration at main.go:5

注意 vet 不会报告全部被覆盖的变量，可以使用 go-nyet 来做进一步的检测：
&gt; $GOPATH/bin/go-nyet main.gomain.go:10:3:Shadowing variable `x`

8. 显式类型的变量无法使用 nil 来初始化nil 是 interface、function、pointer、map、slice 和 channel 类型变量的默认初始值。但声明时不指定类型，编译器也无法推断出变量的具体类型。
// 错误示例func main() &#123;    var x = nil    // error: use of untyped nil    _ = x&#125;// 正确示例func main() &#123;    var x interface&#123;&#125; = nil    _ = x&#125;

9. 直接使用值为 nil 的 slice、map允许对值为 nil 的 slice 添加元素，但对值为 nil 的 map 添加元素则会造成运行时 panic
// map 错误示例func main() &#123;    var m map[string]int    m[&quot;one&quot;] = 1        // error: panic: assignment to entry in nil map    // m := make(map[string]int)// map 的正确声明，分配了实际的内存&#125;// slice 正确示例func main() &#123;    var s []int    s = append(s, 1)&#125;

10. map 容量在创建 map 类型的变量时可以指定容量，但不能像 slice 一样使用 cap() 来检测分配空间的大小：
// 错误示例func main() &#123;    m := make(map[string]int, 99)    println(cap(m))     // error: invalid argument m1 (type map[string]int) for cap&#125;

11. string 类型的变量值不能为 nil对那些喜欢用 nil 初始化字符串的人来说，这就是坑：
// 错误示例func main() &#123;    var s string = nil    // cannot use nil as type string in assignment    if s == nil &#123;    // invalid operation: s == nil (mismatched types string and nil)        s = &quot;default&quot;    &#125;&#125;// 正确示例func main() &#123;    var s string    // 字符串类型的零值是空串 &quot;&quot;    if s == &quot;&quot; &#123;        s = &quot;default&quot;    &#125;&#125;

12. Array 类型的值作为函数参数在 C/C++ 中，数组（名）是指针。将数组作为参数传进函数时，相当于传递了数组内存地址的引用，在函数内部会改变该数组的值。
在 Go 中，数组是值。作为参数传进函数时，传递的是数组的原始值拷贝，此时在函数内部是无法更新该数组的：
// 数组使用值拷贝传参func main() &#123;    x := [3]int&#123;1,2,3&#125;    func(arr [3]int) &#123;        arr[0] = 7        fmt.Println(arr)    // [7 2 3]    &#125;(x)    fmt.Println(x)            // [1 2 3]    // 并不是你以为的 [7 2 3]&#125;

如果想修改参数数组：

直接传递指向这个数组的指针类型：

// 传址会修改原数据func main() &#123;    x := [3]int&#123;1,2,3&#125;    func(arr *[3]int) &#123;        (*arr)[0] = 7        fmt.Println(arr)    // &amp;[7 2 3]    &#125;(&amp;x)    fmt.Println(x)    // [7 2 3]&#125;


直接使用 slice：即使函数内部得到的是 slice 的值拷贝，但依旧会更新 slice 的原始数据（底层 array）

// 会修改 slice 的底层 array，从而修改 slicefunc main() &#123;    x := []int&#123;1, 2, 3&#125;    func(arr []int) &#123;        arr[0] = 7        fmt.Println(x)    // [7 2 3]    &#125;(x)    fmt.Println(x)    // [7 2 3]&#125;

13. range 遍历 slice 和 array 时混淆了返回值与其他编程语言中的 for-in 、foreach 遍历语句不同，Go 中的 range 在遍历时会生成 2 个值，第一个是元素索引，第二个是元素的值：
// 错误示例func main() &#123;    x := []string&#123;&quot;a&quot;, &quot;b&quot;, &quot;c&quot;&#125;    for v := range x &#123;        fmt.Println(v)    // 0 1 2    &#125;&#125;// 正确示例func main() &#123;    x := []string&#123;&quot;a&quot;, &quot;b&quot;, &quot;c&quot;&#125;    for _, v := range x &#123;    // 使用 _ 丢弃索引        fmt.Println(v)    &#125;&#125;

14. slice 和 array 其实是一维数据看起来 Go 支持多维的 array 和 slice，可以创建数组的数组、切片的切片，但其实并不是。
对依赖动态计算多维数组值的应用来说，就性能和复杂度而言，用 Go 实现的效果并不理想。
可以使用原始的一维数组、“独立“ 的切片、“共享底层数组”的切片来创建动态的多维数组。

使用原始的一维数组：要做好索引检查、溢出检测、以及当数组满时再添加值时要重新做内存分配。
使用“独立”的切片分两步：


创建外部 slice

对每个内部 slice 进行内存分配注意内部的 slice 相互独立，使得任一内部 slice 增缩都不会影响到其他的 slice


// 使用各自独立的 6 个 slice 来创建 [2][3] 的动态多维数组func main() &#123;    x := 2    y := 4    table := make([][]int, x)    for i  := range table &#123;        table[i] = make([]int, y)    &#125;&#125;


使用“共享底层数组”的切片


创建一个存放原始数据的容器 slice

创建其他的 slice

切割原始 slice 来初始化其他的 slice


func main() &#123;    h, w := 2, 4    raw := make([]int, h*w)    for i := range raw &#123;        raw[i] = i    &#125;    // 初始化原始 slice    fmt.Println(raw, &amp;raw[4])    // [0 1 2 3 4 5 6 7] 0xc420012120    table := make([][]int, h)    for i := range table &#123;        // 等间距切割原始 slice，创建动态多维数组 table        // 0: raw[0*4: 0*4 + 4]        // 1: raw[1*4: 1*4 + 4]        table[i] = raw[i*w : i*w + w]    &#125;    fmt.Println(table, &amp;table[1][0])    // [[0 1 2 3] [4 5 6 7]] 0xc420012120&#125;

更多关于多维数组的参考
go-how-is-two-dimensional-arrays-memory-representation
what-is-a-concise-way-to-create-a-2d-slice-in-go
15. 访问 map 中不存在的 key和其他编程语言类似，如果访问了 map 中不存在的 key 则希望能返回 nil，比如在 PHP 中：
&gt; php -r &#x27;$v = [&quot;x&quot;=&gt;1, &quot;y&quot;=&gt;2]; @var_dump($v[&quot;z&quot;]);&#x27;NULL

Go 则会返回元素对应数据类型的零值，比如 nil、&#39;&#39; 、false 和 0，取值操作总有值返回，故不能通过取出来的值来判断 key 是不是在 map 中。
检查 key 是否存在可以用 map 直接访问，检查返回的第二个参数即可：
// 错误的 key 检测方式func main() &#123;    x := map[string]string&#123;&quot;one&quot;: &quot;2&quot;, &quot;two&quot;: &quot;&quot;, &quot;three&quot;: &quot;3&quot;&#125;    if v := x[&quot;two&quot;]; v == &quot;&quot; &#123;        fmt.Println(&quot;key two is no entry&quot;)    // 键 two 存不存在都会返回的空字符串    &#125;&#125;// 正确示例func main() &#123;    x := map[string]string&#123;&quot;one&quot;: &quot;2&quot;, &quot;two&quot;: &quot;&quot;, &quot;three&quot;: &quot;3&quot;&#125;    if _, ok := x[&quot;two&quot;]; !ok &#123;        fmt.Println(&quot;key two is no entry&quot;)    &#125;&#125;

16. string 类型的值是常量，不可更改尝试使用索引遍历字符串，来更新字符串中的个别字符，是不允许的。
string 类型的值是只读的二进制 byte slice，如果真要修改字符串中的字符，将 string 转为 []byte 修改后，再转为 string 即可：
// 修改字符串的错误示例func main() &#123;    x := &quot;text&quot;    x[0] = &quot;T&quot;        // error: cannot assign to x[0]    fmt.Println(x)&#125;// 修改示例func main() &#123;    x := &quot;text&quot;    xBytes := []byte(x)    xBytes[0] = &#x27;T&#x27;    // 注意此时的 T 是 rune 类型    x = string(xBytes)    fmt.Println(x)    // Text&#125;

注意： 上边的示例并不是更新字符串的正确姿势，因为一个 UTF8 编码的字符可能会占多个字节，比如汉字就需要 3~4 个字节来存储，此时更新其中的一个字节是错误的。
更新字串的正确姿势：将 string 转为 rune slice（此时 1 个 rune 可能占多个 byte），直接更新 rune 中的字符
func main() &#123;    x := &quot;text&quot;    xRunes := []rune(x)    xRunes[0] = &#x27;我&#x27;    x = string(xRunes)    fmt.Println(x)    // 我ext&#125;

17. string 与 byte slice 之间的转换当进行 string 和 byte slice 相互转换时，参与转换的是拷贝的原始值。这种转换的过程，与其他编程语的强制类型转换操作不同，也和新 slice 与旧 slice 共享底层数组不同。
Go 在 string 与 byte slice 相互转换上优化了两点，避免了额外的内存分配：

在 map[string] 中查找 key 时，使用了对应的 []byte，避免做 m[string(key)] 的内存分配
使用 for range 迭代 string 转换为 []byte 的迭代：for i,v := range []byte(str) &#123;...&#125;

雾：参考原文
18. string 与索引操作符对字符串用索引访问返回的不是字符，而是一个 byte 值。
这种处理方式和其他语言一样，比如 PHP 中：
&gt; php -r &#x27;$name=&quot;中文&quot;; var_dump($name);&#x27;    # &quot;中文&quot; 占用 6 个字节string(6) &quot;中文&quot;&gt; php -r &#x27;$name=&quot;中文&quot;; var_dump($name[0]);&#x27; # 把第一个字节当做 Unicode 字符读取，显示 U+FFFDstring(1) &quot;�&quot;&gt; php -r &#x27;$name=&quot;中文&quot;; var_dump($name[0].$name[1].$name[2]);&#x27;string(3) &quot;中&quot;

func main() &#123;    x := &quot;ascii&quot;    fmt.Println(x[0])        // 97    fmt.Printf(&quot;%T\n&quot;, x[0])// uint8&#125;

如果需要使用 for range 迭代访问字符串中的字符（unicode code point / rune），标准库中有 &quot;unicode/utf8&quot; 包来做 UTF8 的相关解码编码。另外 utf8string 也有像 func (s *String) At(i int) rune 等很方便的库函数。
19. 字符串并不都是 UTF8 文本string 的值不必是 UTF8 文本，可以包含任意的值。只有字符串是文字字面值时才是 UTF8 文本，字串可以通过转义来包含其他数据。
判断字符串是否是 UTF8 文本，可使用 “unicode/utf8” 包中的 ValidString() 函数：
func main() &#123;    str1 := &quot;ABC&quot;    fmt.Println(utf8.ValidString(str1))    // true    str2 := &quot;A\xfeC&quot;    fmt.Println(utf8.ValidString(str2))    // false    str3 := &quot;A\\xfeC&quot;    fmt.Println(utf8.ValidString(str3))    // true    // 把转义字符转义成字面值&#125;

20. 字符串的长度在 Python 中：
data = u&#x27;♥&#x27;print(len(data)) # 1

然而在 Go 中：
func main() &#123;    char := &quot;♥&quot;    fmt.Println(len(char))    // 3&#125;

Go 的内建函数 len() 返回的是字符串的 byte 数量，而不是像 Python 中那样是计算 Unicode 字符数。
如果要得到字符串的字符数，可使用 “unicode/utf8” 包中的 RuneCountInString(str string) (n int)
func main() &#123;    char := &quot;♥&quot;    fmt.Println(utf8.RuneCountInString(char))    // 1&#125;

注意：RuneCountInString 并不总是返回我们看到的字符数，因为有的字符会占用 2 个 rune：
func main() &#123;    char := &quot;é&quot;    fmt.Println(len(char))    // 3    fmt.Println(utf8.RuneCountInString(char))    // 2    fmt.Println(&quot;cafe\u0301&quot;)    // café    // 法文的 cafe，实际上是两个 rune 的组合&#125;

参考：normalization
21. 在多行 array、slice、map 语句中缺少 , 号func main() &#123;    x := []int &#123;        1,        2    // syntax error: unexpected newline, expecting comma or &#125;    &#125;    y := []int&#123;1,2,&#125;    z := []int&#123;1,2&#125;    // ...&#125;

声明语句中 &#125; 折叠到单行后，尾部的 , 不是必需的。
22. log.Fatal 和 log.Panic 不只是 loglog 标准库提供了不同的日志记录等级，与其他语言的日志库不同，Go 的 log 包在调用 Fatal*()、Panic*() 时能做更多日志外的事，如中断程序的执行等：
func main() &#123;    log.Fatal(&quot;Fatal level log: log entry&quot;)        // 输出信息后，程序终止执行    log.Println(&quot;Nomal level log: log entry&quot;)&#125;

23. 对内建数据结构的操作并不是同步的尽管 Go 本身有大量的特性来支持并发，但并不保证并发的数据安全，用户需自己保证变量等数据以原子操作更新。
goroutine 和 channel 是进行原子操作的好方法，或使用 “sync” 包中的锁。
24. range 迭代 string 得到的值range 得到的索引是字符值（Unicode point / rune）第一个字节的位置，与其他编程语言不同，这个索引并不直接是字符在字符串中的位置。
注意一个字符可能占多个 rune，比如法文单词 café 中的 é。操作特殊字符可使用norm 包。
for range 迭代会尝试将 string 翻译为 UTF8 文本，对任何无效的码点都直接使用 0XFFFD rune（�）UNicode 替代字符来表示。如果 string 中有任何非 UTF8 的数据，应将 string 保存为 byte slice 再进行操作。
func main() &#123;    data := &quot;A\xfe\x02\xff\x04&quot;    for _, v := range data &#123;        fmt.Printf(&quot;%#x &quot;, v)    // 0x41 0xfffd 0x2 0xfffd 0x4    // 错误    &#125;    for _, v := range []byte(data) &#123;        fmt.Printf(&quot;%#x &quot;, v)    // 0x41 0xfe 0x2 0xff 0x4    // 正确    &#125;&#125;

25. range 迭代 map如果你希望以特定的顺序（如按 key 排序）来迭代 map，要注意每次迭代都可能产生不一样的结果。
Go 的运行时是有意打乱迭代顺序的，所以你得到的迭代结果可能不一致。但也并不总会打乱，得到连续相同的 5 个迭代结果也是可能的，如：
func main() &#123;    m := map[string]int&#123;&quot;one&quot;: 1, &quot;two&quot;: 2, &quot;three&quot;: 3, &quot;four&quot;: 4&#125;    for k, v := range m &#123;        fmt.Println(k, v)    &#125;&#125;

如果你去 Go Playground 重复运行上边的代码，输出是不会变的，只有你更新代码它才会重新编译。重新编译后迭代顺序是被打乱的：

26. switch 中的 fallthrough 语句switch 语句中的 case 代码块会默认带上 break，但可以使用 fallthrough 来强制执行下一个 case 代码块。
func main() &#123;    isSpace := func(char byte) bool &#123;        switch char &#123;        case &#x27; &#x27;:    // 空格符会直接 break，返回 false // 和其他语言不一样        // fallthrough    // 返回 true        case &#x27;\t&#x27;:            return true        &#125;        return false    &#125;    fmt.Println(isSpace(&#x27;\t&#x27;))    // true    fmt.Println(isSpace(&#x27; &#x27;))    // false&#125;

不过你可以在 case 代码块末尾使用 fallthrough，强制执行下一个 case 代码块。
也可以改写 case 为多条件判断：
func main() &#123;    isSpace := func(char byte) bool &#123;        switch char &#123;        case &#x27; &#x27;, &#x27;\t&#x27;:            return true        &#125;        return false    &#125;    fmt.Println(isSpace(&#x27;\t&#x27;))    // true    fmt.Println(isSpace(&#x27; &#x27;))    // true&#125;

27. 自增和自减运算很多编程语言都自带前置后置的 ++、-- 运算。但 Go 特立独行，去掉了前置操作，同时 ++、— 只作为运算符而非表达式。
// 错误示例func main() &#123;    data := []int&#123;1, 2, 3&#125;    i := 0    ++i            // syntax error: unexpected ++, expecting &#125;    fmt.Println(data[i++])    // syntax error: unexpected ++, expecting :&#125;// 正确示例func main() &#123;    data := []int&#123;1, 2, 3&#125;    i := 0    i++    fmt.Println(data[i])    // 2&#125;

28. 按位取反很多编程语言使用 ~ 作为一元按位取反（NOT）操作符，Go 重用 ^ XOR 操作符来按位取反：
// 错误的取反操作func main() &#123;    fmt.Println(~2)        // bitwise complement operator is ^&#125;// 正确示例func main() &#123;    var d uint8 = 2    fmt.Printf(&quot;%08b\n&quot;, d)        // 00000010    fmt.Printf(&quot;%08b\n&quot;, ^d)    // 11111101&#125;

同时 ^ 也是按位异或（XOR）操作符。
一个操作符能重用两次，是因为一元的 NOT 操作 NOT 0x02，与二元的 XOR 操作 0x22 XOR 0xff 是一致的。
Go 也有特殊的操作符 AND NOT &amp;^ 操作符，不同位才取1。
func main() &#123;    var a uint8 = 0x82    var b uint8 = 0x02    fmt.Printf(&quot;%08b [A]\n&quot;, a)    fmt.Printf(&quot;%08b [B]\n&quot;, b)    fmt.Printf(&quot;%08b (NOT B)\n&quot;, ^b)    fmt.Printf(&quot;%08b ^ %08b = %08b [B XOR 0xff]\n&quot;, b, 0xff, b^0xff)    fmt.Printf(&quot;%08b ^ %08b = %08b [A XOR B]\n&quot;, a, b, a^b)    fmt.Printf(&quot;%08b &amp; %08b = %08b [A AND B]\n&quot;, a, b, a&amp;b)    fmt.Printf(&quot;%08b &amp;^%08b = %08b [A &#x27;AND NOT&#x27; B]\n&quot;, a, b, a&amp;^b)    fmt.Printf(&quot;%08b&amp;(^%08b)= %08b [A AND (NOT B)]\n&quot;, a, b, a&amp;(^b))&#125;

10000010 [A]00000010 [B]11111101 (NOT B)00000010 ^ 11111111 = 11111101 [B XOR 0xff]10000010 ^ 00000010 = 10000000 [A XOR B]10000010 &amp; 00000010 = 00000010 [A AND B]10000010 &amp;^00000010 = 10000000 [A &#x27;AND NOT&#x27; B]10000010&amp;(^00000010)= 10000000 [A AND (NOT B)]

29. 运算符的优先级除了位清除（bit clear）操作符，Go 也有很多和其他语言一样的位操作符，但优先级另当别论。
func main() &#123;    fmt.Printf(&quot;0x2 &amp; 0x2 + 0x4 -&gt; %#x\n&quot;, 0x2&amp;0x2+0x4)    // &amp; 优先 +    //prints: 0x2 &amp; 0x2 + 0x4 -&gt; 0x6    //Go:    (0x2 &amp; 0x2) + 0x4    //C++:    0x2 &amp; (0x2 + 0x4) -&gt; 0x2    fmt.Printf(&quot;0x2 + 0x2 &lt;&lt; 0x1 -&gt; %#x\n&quot;, 0x2+0x2&lt;&lt;0x1)    // &lt;&lt; 优先 +    //prints: 0x2 + 0x2 &lt;&lt; 0x1 -&gt; 0x6    //Go:     0x2 + (0x2 &lt;&lt; 0x1)    //C++:   (0x2 + 0x2) &lt;&lt; 0x1 -&gt; 0x8    fmt.Printf(&quot;0xf | 0x2 ^ 0x2 -&gt; %#x\n&quot;, 0xf|0x2^0x2)    // | 优先 ^    //prints: 0xf | 0x2 ^ 0x2 -&gt; 0xd    //Go:    (0xf | 0x2) ^ 0x2    //C++:    0xf | (0x2 ^ 0x2) -&gt; 0xf&#125;

优先级列表：
Precedence    Operator    5             *  /  %  &lt;&lt;  &gt;&gt;  &amp;  &amp;^    4             +  -  |  ^    3             ==  !=  &lt;  &lt;=  &gt;  &gt;=    2             &amp;&amp;    1             ||

30. 不导出的 struct 字段无法被 encode以小写字母开头的字段成员是无法被外部直接访问的，所以 struct 在进行 json、xml、gob 等格式的 encode 操作时，这些私有字段会被忽略，导出时得到零值：
func main() &#123;    in := MyData&#123;1, &quot;two&quot;&#125;    fmt.Printf(&quot;%#v\n&quot;, in)    // main.MyData&#123;One:1, two:&quot;two&quot;&#125;    encoded, _ := json.Marshal(in)    fmt.Println(string(encoded))    // &#123;&quot;One&quot;:1&#125;    // 私有字段 two 被忽略了    var out MyData    json.Unmarshal(encoded, &amp;out)    fmt.Printf(&quot;%#v\n&quot;, out)     // main.MyData&#123;One:1, two:&quot;&quot;&#125;&#125;

31. 程序退出时还有 goroutine 在执行程序默认不等所有 goroutine 都执行完才退出，这点需要特别注意：
// 主程序会直接退出func main() &#123;    workerCount := 2    for i := 0; i &lt; workerCount; i++ &#123;        go doIt(i)    &#125;    time.Sleep(1 * time.Second)    fmt.Println(&quot;all done!&quot;)&#125;func doIt(workerID int) &#123;    fmt.Printf(&quot;[%v] is running\n&quot;, workerID)    time.Sleep(3 * time.Second)        // 模拟 goroutine 正在执行    fmt.Printf(&quot;[%v] is done\n&quot;, workerID)&#125;

如下，main() 主程序不等两个 goroutine 执行完就直接退出了：

常用解决办法：使用 “WaitGroup” 变量，它会让主程序等待所有 goroutine 执行完毕再退出。
如果你的 goroutine 要做消息的循环处理等耗时操作，可以向它们发送一条 kill 消息来关闭它们。或直接关闭一个它们都等待接收数据的 channel：
// 等待所有 goroutine 执行完毕// 进入死锁func main() &#123;    var wg sync.WaitGroup    done := make(chan struct&#123;&#125;)    workerCount := 2    for i := 0; i &lt; workerCount; i++ &#123;        wg.Add(1)        go doIt(i, done, wg)    &#125;    close(done)    wg.Wait()    fmt.Println(&quot;all done!&quot;)&#125;func doIt(workerID int, done &lt;-chan struct&#123;&#125;, wg sync.WaitGroup) &#123;    fmt.Printf(&quot;[%v] is running\n&quot;, workerID)    defer wg.Done()    &lt;-done    fmt.Printf(&quot;[%v] is done\n&quot;, workerID)&#125;

执行结果：

看起来好像 goroutine 都执行完了，然而报错：
fatal error: all goroutines are asleep - deadlock!
为什么会发生死锁？goroutine 在退出前调用了 wg.Done() ，程序应该正常退出的。
原因是 goroutine 得到的 “WaitGroup” 变量是 var wg WaitGroup 的一份拷贝值，即 doIt() 传参只传值。所以哪怕在每个 goroutine 中都调用了 wg.Done()， 主程序中的 wg 变量并不会受到影响。
// 等待所有 goroutine 执行完毕// 使用传址方式为 WaitGroup 变量传参// 使用 channel 关闭 goroutinefunc main() &#123;    var wg sync.WaitGroup    done := make(chan struct&#123;&#125;)    ch := make(chan interface&#123;&#125;)    workerCount := 2    for i := 0; i &lt; workerCount; i++ &#123;        wg.Add(1)        go doIt(i, ch, done, &amp;wg)    // wg 传指针，doIt() 内部会改变 wg 的值    &#125;    for i := 0; i &lt; workerCount; i++ &#123;    // 向 ch 中发送数据，关闭 goroutine        ch &lt;- i    &#125;    close(done)    wg.Wait()    close(ch)    fmt.Println(&quot;all done!&quot;)&#125;func doIt(workerID int, ch &lt;-chan interface&#123;&#125;, done &lt;-chan struct&#123;&#125;, wg *sync.WaitGroup) &#123;    fmt.Printf(&quot;[%v] is running\n&quot;, workerID)    defer wg.Done()    for &#123;        select &#123;        case m := &lt;-ch:            fmt.Printf(&quot;[%v] m =&gt; %v\n&quot;, workerID, m)        case &lt;-done:            fmt.Printf(&quot;[%v] is done\n&quot;, workerID)            return        &#125;    &#125;&#125;

运行效果：

32. 向无缓冲的 channel 发送数据，只要 receiver 准备好了就会立刻返回只有在数据被 receiver 处理时，sender 才会阻塞。因运行环境而异，在 sender 发送完数据后，receiver 的 goroutine 可能没有足够的时间处理下一个数据。如：
func main() &#123;    ch := make(chan string)    go func() &#123;        for m := range ch &#123;            fmt.Println(&quot;Processed:&quot;, m)            time.Sleep(1 * time.Second)    // 模拟需要长时间运行的操作        &#125;    &#125;()    ch &lt;- &quot;cmd.1&quot;    ch &lt;- &quot;cmd.2&quot; // 不会被接收处理&#125;

运行效果：

33. 向已关闭的 channel 发送数据会造成 panic从已关闭的 channel 接收数据是安全的：
接收状态值 ok 是 false 时表明 channel 中已没有数据可以接收了。类似的，从有缓冲的 channel 中接收数据，缓存的数据获取完再没有数据可取时，状态值也是 false
向已关闭的 channel 中发送数据会造成 panic：
func main() &#123;    ch := make(chan int)    for i := 0; i &lt; 3; i++ &#123;        go func(idx int) &#123;            ch &lt;- idx        &#125;(i)    &#125;    fmt.Println(&lt;-ch)        // 输出第一个发送的值    close(ch)            // 不能关闭，还有其他的 sender    time.Sleep(2 * time.Second)    // 模拟做其他的操作&#125;

运行结果：

针对上边有 bug 的这个例子，可使用一个废弃 channel done 来告诉剩余的 goroutine 无需再向 ch 发送数据。此时 &lt;- done 的结果是 &#123;&#125;：
func main() &#123;    ch := make(chan int)    done := make(chan struct&#123;&#125;)    for i := 0; i &lt; 3; i++ &#123;        go func(idx int) &#123;            select &#123;            case ch &lt;- (idx + 1) * 2:                fmt.Println(idx, &quot;Send result&quot;)            case &lt;-done:                fmt.Println(idx, &quot;Exiting&quot;)            &#125;        &#125;(i)    &#125;    fmt.Println(&quot;Result: &quot;, &lt;-ch)    close(done)    time.Sleep(3 * time.Second)&#125;

运行效果：

34. 使用了值为 nil 的 channel在一个值为 nil 的 channel 上发送和接收数据将永久阻塞：
func main() &#123;    var ch chan int // 未初始化，值为 nil    for i := 0; i &lt; 3; i++ &#123;        go func(i int) &#123;            ch &lt;- i        &#125;(i)    &#125;    fmt.Println(&quot;Result: &quot;, &lt;-ch)    time.Sleep(2 * time.Second)&#125;

runtime 死锁错误：
fatal error: all goroutines are asleep - deadlock!
goroutine 1 [chan receive (nil chan)]
利用这个死锁的特性，可以用在 select 中动态的打开和关闭 case 语句块：
func main() &#123;    inCh := make(chan int)    outCh := make(chan int)    go func() &#123;        var in &lt;-chan int = inCh        var out chan&lt;- int        var val int        for &#123;            select &#123;            case out &lt;- val:                println(&quot;--------&quot;)                out = nil                in = inCh            case val = &lt;-in:                println(&quot;++++++++++&quot;)                out = outCh                in = nil            &#125;        &#125;    &#125;()    go func() &#123;        for r := range outCh &#123;            fmt.Println(&quot;Result: &quot;, r)        &#125;    &#125;()    time.Sleep(0)    inCh &lt;- 1    inCh &lt;- 2    time.Sleep(3 * time.Second)&#125;

运行效果：

34. 若函数 receiver 传参是传值方式，则无法修改参数的原有值方法 receiver 的参数与一般函数的参数类似：如果声明为值，那方法体得到的是一份参数的值拷贝，此时对参数的任何修改都不会对原有值产生影响。
除非 receiver 参数是 map 或 slice 类型的变量，并且是以指针方式更新 map 中的字段、slice 中的元素的，才会更新原有值:
type data struct &#123;    num   int    key   *string    items map[string]bool&#125;func (this *data) pointerFunc() &#123;    this.num = 7&#125;func (this data) valueFunc() &#123;    this.num = 8    *this.key = &quot;valueFunc.key&quot;    this.items[&quot;valueFunc&quot;] = true&#125;func main() &#123;    key := &quot;key1&quot;    d := data&#123;1, &amp;key, make(map[string]bool)&#125;    fmt.Printf(&quot;num=%v  key=%v  items=%v\n&quot;, d.num, *d.key, d.items)    d.pointerFunc()    // 修改 num 的值为 7    fmt.Printf(&quot;num=%v  key=%v  items=%v\n&quot;, d.num, *d.key, d.items)    d.valueFunc()    // 修改 key 和 items 的值    fmt.Printf(&quot;num=%v  key=%v  items=%v\n&quot;, d.num, *d.key, d.items)&#125;

运行结果：

中级篇：35-5035. 关闭 HTTP 的响应体使用 HTTP 标准库发起请求、获取响应时，即使你不从响应中读取任何数据或响应为空，都需要手动关闭响应体。新手很容易忘记手动关闭，或者写在了错误的位置：
// 请求失败造成 panicfunc main() &#123;    resp, err := http.Get(&quot;https://api.ipify.org?format=json&quot;)    defer resp.Body.Close()    // resp 可能为 nil，不能读取 Body    if err != nil &#123;        fmt.Println(err)        return    &#125;    body, err := ioutil.ReadAll(resp.Body)    checkError(err)    fmt.Println(string(body))&#125;func checkError(err error) &#123;    if err != nil&#123;        log.Fatalln(err)    &#125;&#125;

上边的代码能正确发起请求，但是一旦请求失败，变量 resp 值为 nil，造成 panic：
panic: runtime error: invalid memory address or nil pointer dereference
应该先检查HTTP 响应错误为 nil，再调用 resp.Body.Close() 来关闭响应体：
// 大多数情况正确的示例func main() &#123;    resp, err := http.Get(&quot;https://api.ipify.org?format=json&quot;)    checkError(err)    defer resp.Body.Close()    // 绝大多数情况下的正确关闭方式    body, err := ioutil.ReadAll(resp.Body)    checkError(err)    fmt.Println(string(body))&#125;

输出：
Get https://api.ipify.org?format=…: x509: certificate signed by unknown authority
绝大多数请求失败的情况下，resp 的值为 nil 且 err 为 non-nil。但如果你得到的是重定向错误，那它俩的值都是 non-nil，最后依旧可能发生内存泄露。2 个解决办法：

可以直接在处理 HTTP 响应错误的代码块中，直接关闭非 nil 的响应体。
手动调用 defer 来关闭响应体：

// 正确示例func main() &#123;    resp, err := http.Get(&quot;http://www.baidu.com&quot;)    // 关闭 resp.Body 的正确姿势    if resp != nil &#123;        defer resp.Body.Close()    &#125;    checkError(err)    defer resp.Body.Close()    body, err := ioutil.ReadAll(resp.Body)    checkError(err)    fmt.Println(string(body))&#125;

resp.Body.Close() 早先版本的实现是读取响应体的数据之后丢弃，保证了 keep-alive 的 HTTP 连接能重用处理不止一个请求。但 Go 的最新版本将读取并丢弃数据的任务交给了用户，如果你不处理，HTTP 连接可能会直接关闭而非重用，参考在 Go 1.5 版本文档。
如果程序大量重用 HTTP 长连接，你可能要在处理响应的逻辑代码中加入：
_, err = io.Copy(ioutil.Discard, resp.Body)    // 手动丢弃读取完毕的数据

如果你需要完整读取响应，上边的代码是需要写的。比如在解码 API 的 JSON 响应数据：
json.NewDecoder(resp.Body).Decode(&amp;data)

36. 关闭 HTTP 连接一些支持 HTTP1.1 或 HTTP1.0 配置了 connection: keep-alive 选项的服务器会保持一段时间的长连接。但标准库 “net/http” 的连接默认只在服务器主动要求关闭时才断开，所以你的程序可能会消耗完 socket 描述符。解决办法有 2 个，请求结束后：

直接设置请求变量的 Close 字段值为 true，每次请求结束后就会主动关闭连接。
设置 Header 请求头部选项 Connection: close，然后服务器返回的响应头部也会有这个选项，此时 HTTP 标准库会主动断开连接。

// 主动关闭连接func main() &#123;    req, err := http.NewRequest(&quot;GET&quot;, &quot;http://golang.org&quot;, nil)    checkError(err)    req.Close = true    //req.Header.Add(&quot;Connection&quot;, &quot;close&quot;)    // 等效的关闭方式    resp, err := http.DefaultClient.Do(req)    if resp != nil &#123;        defer resp.Body.Close()    &#125;    checkError(err)    body, err := ioutil.ReadAll(resp.Body)    checkError(err)    fmt.Println(string(body))&#125;

你可以创建一个自定义配置的 HTTP transport 客户端，用来取消 HTTP 全局的复用连接：
func main() &#123;    tr := http.Transport&#123;DisableKeepAlives: true&#125;    client := http.Client&#123;Transport: &amp;tr&#125;    resp, err := client.Get(&quot;https://golang.google.cn/&quot;)    if resp != nil &#123;        defer resp.Body.Close()    &#125;    checkError(err)    fmt.Println(resp.StatusCode)    // 200    body, err := ioutil.ReadAll(resp.Body)    checkError(err)    fmt.Println(len(string(body)))&#125;

根据需求选择使用场景：

若你的程序要向同一服务器发大量请求，使用默认的保持长连接。
若你的程序要连接大量的服务器，且每台服务器只请求一两次，那收到请求后直接关闭连接。或增加最大文件打开数 fs.file-max 的值。

37. 将 JSON 中的数字解码为 interface 类型在 encode/decode JSON 数据时，Go 默认会将数值当做 float64 处理，比如下边的代码会造成 panic：
func main() &#123;    var data = []byte(`&#123;&quot;status&quot;: 200&#125;`)    var result map[string]interface&#123;&#125;    if err := json.Unmarshal(data, &amp;result); err != nil &#123;        log.Fatalln(err)    &#125;    fmt.Printf(&quot;%T\n&quot;, result[&quot;status&quot;])    // float64    var status = result[&quot;status&quot;].(int)    // 类型断言错误    fmt.Println(&quot;Status value: &quot;, status)&#125;

panic: interface conversion: interface {} is float64, not int
如果你尝试 decode 的 JSON 字段是整型，你可以：

将 int 值转为 float 统一使用
将 decode 后需要的 float 值转为 int 使用

// 将 decode 的值转为 int 使用func main() &#123;    var data = []byte(`&#123;&quot;status&quot;: 200&#125;`)    var result map[string]interface&#123;&#125;    if err := json.Unmarshal(data, &amp;result); err != nil &#123;        log.Fatalln(err)    &#125;    var status = uint64(result[&quot;status&quot;].(float64))    fmt.Println(&quot;Status value: &quot;, status)&#125;


使用 Decoder 类型来 decode JSON 数据，明确表示字段的值类型

// 指定字段类型func main() &#123;    var data = []byte(`&#123;&quot;status&quot;: 200&#125;`)    var result map[string]interface&#123;&#125;    var decoder = json.NewDecoder(bytes.NewReader(data))    decoder.UseNumber()    if err := decoder.Decode(&amp;result); err != nil &#123;        log.Fatalln(err)    &#125;    var status, _ = result[&quot;status&quot;].(json.Number).Int64()    fmt.Println(&quot;Status value: &quot;, status)&#125; // 你可以使用 string 来存储数值数据，在 decode 时再决定按 int 还是 float 使用 // 将数据转为 decode 为 string func main() &#123;     var data = []byte(&#123;&quot;status&quot;: 200&#125;)      var result map[string]interface&#123;&#125;      var decoder = json.NewDecoder(bytes.NewReader(data))      decoder.UseNumber()      if err := decoder.Decode(&amp;result); err != nil &#123;          log.Fatalln(err)      &#125;    var status uint64      err := json.Unmarshal([]byte(result[&quot;status&quot;].(json.Number).String()), &amp;status);    checkError(err)       fmt.Println(&quot;Status value: &quot;, status)&#125;

- 使用 struct 类型将你需要的数据映射为数值型
// struct 中指定字段类型func main() &#123;      var data = []byte(`&#123;&quot;status&quot;: 200&#125;`)      var result struct &#123;          Status uint64 `json:&quot;status&quot;`      &#125;      err := json.NewDecoder(bytes.NewReader(data)).Decode(&amp;result)      checkError(err)    fmt.Printf(&quot;Result: %+v&quot;, result)&#125;


可以使用 struct 将数值类型映射为 json.RawMessage 原生数据类型适用于如果 JSON 数据不着急 decode 或 JSON 某个字段的值类型不固定等情况：

// 状态名称可能是 int 也可能是 string，指定为 json.RawMessage 类型func main() &#123;    records := [][]byte&#123;        []byte(`&#123;&quot;status&quot;:200, &quot;tag&quot;:&quot;one&quot;&#125;`),        []byte(`&#123;&quot;status&quot;:&quot;ok&quot;, &quot;tag&quot;:&quot;two&quot;&#125;`),    &#125;    for idx, record := range records &#123;        var result struct &#123;            StatusCode uint64            StatusName string            Status     json.RawMessage `json:&quot;status&quot;`            Tag        string          `json:&quot;tag&quot;`        &#125;        err := json.NewDecoder(bytes.NewReader(record)).Decode(&amp;result)        checkError(err)        var name string        err = json.Unmarshal(result.Status, &amp;name)        if err == nil &#123;            result.StatusName = name        &#125;        var code uint64        err = json.Unmarshal(result.Status, &amp;code)        if err == nil &#123;            result.StatusCode = code        &#125;        fmt.Printf(&quot;[%v] result =&gt; %+v\n&quot;, idx, result)    &#125;&#125;

38. struct、array、slice 和 map 的值比较可以使用相等运算符 == 来比较结构体变量，前提是两个结构体的成员都是可比较的类型：
type data struct &#123;    num     int    fp      float32    complex complex64    str     string    char    rune    yes     bool    events  &lt;-chan string    handler interface&#123;&#125;    ref     *byte    raw     [10]byte&#125;func main() &#123;    v1 := data&#123;&#125;    v2 := data&#123;&#125;    fmt.Println(&quot;v1 == v2: &quot;, v1 == v2)    // true&#125;

如果两个结构体中有任意成员是不可比较的，将会造成编译错误。注意数组成员只有在数组元素可比较时候才可比较。
type data struct &#123;    num    int    checks [10]func() bool        // 无法比较    doIt   func() bool        // 无法比较    m      map[string]string    // 无法比较    bytes  []byte            // 无法比较&#125;func main() &#123;    v1 := data&#123;&#125;    v2 := data&#123;&#125;    fmt.Println(&quot;v1 == v2: &quot;, v1 == v2)&#125;

invalid operation: v1 == v2 (struct containing [10]func() bool cannot be compared)
Go 提供了一些库函数来比较那些无法使用 == 比较的变量，比如使用 “reflect” 包的 DeepEqual() ：
// 比较相等运算符无法比较的元素func main() &#123;    v1 := data&#123;&#125;    v2 := data&#123;&#125;    fmt.Println(&quot;v1 == v2: &quot;, reflect.DeepEqual(v1, v2))    // true    m1 := map[string]string&#123;&quot;one&quot;: &quot;a&quot;, &quot;two&quot;: &quot;b&quot;&#125;    m2 := map[string]string&#123;&quot;two&quot;: &quot;b&quot;, &quot;one&quot;: &quot;a&quot;&#125;    fmt.Println(&quot;v1 == v2: &quot;, reflect.DeepEqual(m1, m2))    // true    s1 := []int&#123;1, 2, 3&#125;    s2 := []int&#123;1, 2, 3&#125;       // 注意两个 slice 相等，值和顺序必须一致    fmt.Println(&quot;v1 == v2: &quot;, reflect.DeepEqual(s1, s2))    // true&#125;

这种比较方式可能比较慢，根据你的程序需求来使用。DeepEqual() 还有其他用法：
func main() &#123;    var b1 []byte = nil    b2 := []byte&#123;&#125;    fmt.Println(&quot;b1 == b2: &quot;, reflect.DeepEqual(b1, b2))    // false&#125;

注意：

DeepEqual() 并不总适合于比较 slice

func main() &#123;    var str = &quot;one&quot;    var in interface&#123;&#125; = &quot;one&quot;    fmt.Println(&quot;str == in: &quot;, reflect.DeepEqual(str, in))    // true    v1 := []string&#123;&quot;one&quot;, &quot;two&quot;&#125;    v2 := []string&#123;&quot;two&quot;, &quot;one&quot;&#125;    fmt.Println(&quot;v1 == v2: &quot;, reflect.DeepEqual(v1, v2))    // false    data := map[string]interface&#123;&#125;&#123;        &quot;code&quot;:  200,        &quot;value&quot;: []string&#123;&quot;one&quot;, &quot;two&quot;&#125;,    &#125;    encoded, _ := json.Marshal(data)    var decoded map[string]interface&#123;&#125;    json.Unmarshal(encoded, &amp;decoded)    fmt.Println(&quot;data == decoded: &quot;, reflect.DeepEqual(data, decoded))    // false&#125;

如果要大小写不敏感来比较 byte 或 string 中的英文文本，可以使用 “bytes” 或 “strings” 包的 ToUpper() 和 ToLower() 函数。比较其他语言的 byte 或 string，应使用 bytes.EqualFold() 和 strings.EqualFold()
如果 byte slice 中含有验证用户身份的数据（密文哈希、token 等），不应再使用 reflect.DeepEqual()、bytes.Equal()、 bytes.Compare()。这三个函数容易对程序造成 timing attacks，此时应使用 “crypto/subtle” 包中的 subtle.ConstantTimeCompare() 等函数

reflect.DeepEqual() 认为空 slice 与 nil slice 并不相等，但注意 byte.Equal() 会认为二者相等：

func main() &#123;    var b1 []byte = nil    b2 := []byte&#123;&#125;    // b1 与 b2 长度相等、有相同的字节序    // nil 与 slice 在字节上是相同的    fmt.Println(&quot;b1 == b2: &quot;, bytes.Equal(b1, b2))    // true&#125;

39. 从 panic 中恢复在一个 defer 延迟执行的函数中调用 recover() ，它便能捕捉 / 中断 panic
// 错误的 recover 调用示例func main() &#123;    recover()    // 什么都不会捕捉    panic(&quot;not good&quot;)    // 发生 panic，主程序退出    recover()    // 不会被执行    println(&quot;ok&quot;)&#125;// 正确的 recover 调用示例func main() &#123;    defer func() &#123;        fmt.Println(&quot;recovered: &quot;, recover())    &#125;()    panic(&quot;not good&quot;)&#125;

从上边可以看出，recover() 仅在 defer 执行的函数中调用才会生效。
// 错误的调用示例func main() &#123;    defer func() &#123;        doRecover()    &#125;()    panic(&quot;not good&quot;)&#125;func doRecover() &#123;    fmt.Println(&quot;recobered: &quot;, recover())&#125;

recobered:  panic: not good
40. 在 range 迭代 slice、array、map 时通过更新引用来更新元素在 range 迭代中，得到的值其实是元素的一份值拷贝，更新拷贝并不会更改原来的元素，即是拷贝的地址并不是原有元素的地址：
func main() &#123;    data := []int&#123;1, 2, 3&#125;    for _, v := range data &#123;        v *= 10        // data 中原有元素是不会被修改的    &#125;    fmt.Println(&quot;data: &quot;, data)    // data:  [1 2 3]&#125;

如果要修改原有元素的值，应该使用索引直接访问：
func main() &#123;    data := []int&#123;1, 2, 3&#125;    for i, v := range data &#123;        data[i] = v * 10    &#125;    fmt.Println(&quot;data: &quot;, data)    // data:  [10 20 30]&#125;

如果你的集合保存的是指向值的指针，需稍作修改。依旧需要使用索引访问元素，不过可以使用 range 出来的元素直接更新原有值：
func main() &#123;    data := []*struct&#123; num int &#125;&#123;&#123;1&#125;, &#123;2&#125;, &#123;3&#125;,&#125;    for _, v := range data &#123;        v.num *= 10    // 直接使用指针更新    &#125;    fmt.Println(data[0], data[1], data[2])    // &amp;&#123;10&#125; &amp;&#123;20&#125; &amp;&#123;30&#125;&#125;

41. slice 中隐藏的数据从 slice 中重新切出新 slice 时，新 slice 会引用原 slice 的底层数组。如果跳了这个坑，程序可能会分配大量的临时 slice 来指向原底层数组的部分数据，将导致难以预料的内存使用。
func get() []byte &#123;    raw := make([]byte, 10000)    fmt.Println(len(raw), cap(raw), &amp;raw[0])    // 10000 10000 0xc420080000    return raw[:3]    // 重新分配容量为 10000 的 slice&#125;func main() &#123;    data := get()    fmt.Println(len(data), cap(data), &amp;data[0])    // 3 10000 0xc420080000&#125;

可以通过拷贝临时 slice 的数据，而不是重新切片来解决：
func get() (res []byte) &#123;    raw := make([]byte, 10000)    fmt.Println(len(raw), cap(raw), &amp;raw[0])    // 10000 10000 0xc420080000    res = make([]byte, 3)    copy(res, raw[:3])    return&#125;func main() &#123;    data := get()    fmt.Println(len(data), cap(data), &amp;data[0])    // 3 3 0xc4200160b8&#125;

42. Slice 中数据的误用举个简单例子，重写文件路径（存储在 slice 中）
分割路径来指向每个不同级的目录，修改第一个目录名再重组子目录名，创建新路径：
// 错误使用 slice 的拼接示例func main() &#123;    path := []byte(&quot;AAAA/BBBBBBBBB&quot;)    sepIndex := bytes.IndexByte(path, &#x27;/&#x27;) // 4    println(sepIndex)    dir1 := path[:sepIndex]    dir2 := path[sepIndex+1:]    println(&quot;dir1: &quot;, string(dir1))        // AAAA    println(&quot;dir2: &quot;, string(dir2))        // BBBBBBBBB    dir1 = append(dir1, &quot;suffix&quot;...)       println(&quot;current path: &quot;, string(path))    // AAAAsuffixBBBB    path = bytes.Join([][]byte&#123;dir1, dir2&#125;, []byte&#123;&#x27;/&#x27;&#125;)    println(&quot;dir1: &quot;, string(dir1))        // AAAAsuffix    println(&quot;dir2: &quot;, string(dir2))        // uffixBBBB    println(&quot;new path: &quot;, string(path))    // AAAAsuffix/uffixBBBB    // 错误结果&#125;

拼接的结果不是正确的 AAAAsuffix/BBBBBBBBB，因为 dir1、 dir2 两个 slice 引用的数据都是 path 的底层数组，第 13 行修改 dir1 同时也修改了 path，也导致了 dir2 的修改
解决方法：

重新分配新的 slice 并拷贝你需要的数据
使用完整的 slice 表达式：input[low:high:max]，容量便调整为 max - low

// 使用 full slice expressionfunc main() &#123;    path := []byte(&quot;AAAA/BBBBBBBBB&quot;)    sepIndex := bytes.IndexByte(path, &#x27;/&#x27;) // 4    dir1 := path[:sepIndex:sepIndex]        // 此时 cap(dir1) 指定为4， 而不是先前的 16    dir2 := path[sepIndex+1:]    dir1 = append(dir1, &quot;suffix&quot;...)    path = bytes.Join([][]byte&#123;dir1, dir2&#125;, []byte&#123;&#x27;/&#x27;&#125;)    println(&quot;dir1: &quot;, string(dir1))        // AAAAsuffix    println(&quot;dir2: &quot;, string(dir2))        // BBBBBBBBB    println(&quot;new path: &quot;, string(path))    // AAAAsuffix/BBBBBBBBB&#125;

第 6 行中第三个参数是用来控制 dir1 的新容量，再往 dir1 中 append 超额元素时，将分配新的 buffer 来保存。而不是覆盖原来的 path 底层数组
43. 旧 slice当你从一个已存在的 slice 创建新 slice 时，二者的数据指向相同的底层数组。如果你的程序使用这个特性，那需要注意 “旧”（stale） slice 问题。
某些情况下，向一个 slice 中追加元素而它指向的底层数组容量不足时，将会重新分配一个新数组来存储数据。而其他 slice 还指向原来的旧底层数组。
// 超过容量将重新分配数组来拷贝值、重新存储func main() &#123;    s1 := []int&#123;1, 2, 3&#125;    fmt.Println(len(s1), cap(s1), s1)    // 3 3 [1 2 3 ]    s2 := s1[1:]    fmt.Println(len(s2), cap(s2), s2)    // 2 2 [2 3]    for i := range s2 &#123;        s2[i] += 20    &#125;    // 此时的 s1 与 s2 是指向同一个底层数组的    fmt.Println(s1)        // [1 22 23]    fmt.Println(s2)        // [22 23]    s2 = append(s2, 4)    // 向容量为 2 的 s2 中再追加元素，此时将分配新数组来存    for i := range s2 &#123;        s2[i] += 10    &#125;    fmt.Println(s1)        // [1 22 23]    // 此时的 s1 不再更新，为旧数据    fmt.Println(s2)        // [32 33 14]&#125;

44. 类型声明与方法从一个现有的非 interface 类型创建新类型时，并不会继承原有的方法：
// 定义 Mutex 的自定义类型type myMutex sync.Mutexfunc main() &#123;    var mtx myMutex    mtx.Lock()    mtx.UnLock()&#125;

mtx.Lock undefined (type myMutex has no field or method Lock)…
如果你需要使用原类型的方法，可将原类型以匿名字段的形式嵌到你定义的新 struct 中：
// 类型以字段形式直接嵌入type myLocker struct &#123;    sync.Mutex&#125;func main() &#123;    var locker myLocker    locker.Lock()    locker.Unlock()&#125;

interface 类型声明也保留它的方法集：
type myLocker sync.Lockerfunc main() &#123;    var locker myLocker    locker.Lock()    locker.Unlock()&#125;

45. 跳出 for-switch 和 for-select 代码块没有指定标签的 break 只会跳出 switch/select 语句，若不能使用 return 语句跳出的话，可为 break 跳出标签指定的代码块：
// break 配合 label 跳出指定代码块func main() &#123;loop:    for &#123;        switch &#123;        case true:            fmt.Println(&quot;breaking out...&quot;)            //break    // 死循环，一直打印 breaking out...            break loop        &#125;    &#125;    fmt.Println(&quot;out...&quot;)&#125;

goto 虽然也能跳转到指定位置，但依旧会再次进入 for-switch，死循环。
46. for 语句中的迭代变量与闭包函数for 语句中的迭代变量在每次迭代中都会重用，即 for 中创建的闭包函数接收到的参数始终是同一个变量，在 goroutine 开始执行时都会得到同一个迭代值：
func main() &#123;    data := []string&#123;&quot;one&quot;, &quot;two&quot;, &quot;three&quot;&#125;    for _, v := range data &#123;        go func() &#123;            fmt.Println(v)        &#125;()    &#125;    time.Sleep(3 * time.Second)    // 输出 three three three&#125;

最简单的解决方法：无需修改 goroutine 函数，在 for 内部使用局部变量保存迭代值，再传参：
func main() &#123;    data := []string&#123;&quot;one&quot;, &quot;two&quot;, &quot;three&quot;&#125;    for _, v := range data &#123;        vCopy := v        go func() &#123;            fmt.Println(vCopy)        &#125;()    &#125;    time.Sleep(3 * time.Second)    // 输出 one two three&#125;

另一个解决方法：直接将当前的迭代值以参数形式传递给匿名函数：
func main() &#123;    data := []string&#123;&quot;one&quot;, &quot;two&quot;, &quot;three&quot;&#125;    for _, v := range data &#123;        go func(in string) &#123;            fmt.Println(in)        &#125;(v)    &#125;    time.Sleep(3 * time.Second)    // 输出 one two three&#125;

注意下边这个稍复杂的 3 个示例区别：
type field struct &#123;    name string&#125;func (p *field) print() &#123;    fmt.Println(p.name)&#125;// 错误示例func main() &#123;    data := []field&#123;&#123;&quot;one&quot;&#125;, &#123;&quot;two&quot;&#125;, &#123;&quot;three&quot;&#125;&#125;    for _, v := range data &#123;        go v.print()    &#125;    time.Sleep(3 * time.Second)    // 输出 three three three&#125;// 正确示例func main() &#123;    data := []field&#123;&#123;&quot;one&quot;&#125;, &#123;&quot;two&quot;&#125;, &#123;&quot;three&quot;&#125;&#125;    for _, v := range data &#123;        v := v        go v.print()    &#125;    time.Sleep(3 * time.Second)    // 输出 one two three&#125;// 正确示例func main() &#123;    data := []*field&#123;&#123;&quot;one&quot;&#125;, &#123;&quot;two&quot;&#125;, &#123;&quot;three&quot;&#125;&#125;    for _, v := range data &#123;    // 此时迭代值 v 是三个元素值的地址，每次 v 指向的值不同        go v.print()    &#125;    time.Sleep(3 * time.Second)    // 输出 one two three&#125;

47. defer 函数的参数值对 defer 延迟执行的函数，它的参数会在声明时候就会求出具体值，而不是在执行时才求值：
// 在 defer 函数中参数会提前求值func main() &#123;    var i = 1    defer fmt.Println(&quot;result: &quot;, func() int &#123; return i * 2 &#125;())    i++&#125;

result: 2
48. defer 函数的执行时机对 defer 延迟执行的函数，会在调用它的函数结束时执行，而不是在调用它的语句块结束时执行，注意区分开。
比如在一个长时间执行的函数里，内部 for 循环中使用 defer 来清理每次迭代产生的资源调用，就会出现问题：
// 命令行参数指定目录名// 遍历读取目录下的文件func main() &#123;    if len(os.Args) != 2 &#123;        os.Exit(1)    &#125;    dir := os.Args[1]    start, err := os.Stat(dir)    if err != nil || !start.IsDir() &#123;        os.Exit(2)    &#125;    var targets []string    filepath.Walk(dir, func(fPath string, fInfo os.FileInfo, err error) error &#123;        if err != nil &#123;            return err        &#125;        if !fInfo.Mode().IsRegular() &#123;            return nil        &#125;        targets = append(targets, fPath)        return nil    &#125;)    for _, target := range targets &#123;        f, err := os.Open(target)        if err != nil &#123;            fmt.Println(&quot;bad target:&quot;, target, &quot;error:&quot;, err)    //error:too many open files            break        &#125;        defer f.Close()    // 在每次 for 语句块结束时，不会关闭文件资源        // 使用 f 资源    &#125;&#125;

先创建 10000 个文件：
#!/bin/bashfor n in &#123;1..10000&#125;; do    echo content &gt; &quot;file$&#123;n&#125;.txt&quot;done

运行效果：

解决办法：defer 延迟执行的函数写入匿名函数中：
// 目录遍历正常func main() &#123;    // ...    for _, target := range targets &#123;        func() &#123;            f, err := os.Open(target)            if err != nil &#123;                fmt.Println(&quot;bad target:&quot;, target, &quot;error:&quot;, err)                return    // 在匿名函数内使用 return 代替 break 即可            &#125;            defer f.Close()    // 匿名函数执行结束，调用关闭文件资源            // 使用 f 资源        &#125;()    &#125;&#125;

当然你也可以去掉 defer，在文件资源使用完毕后，直接调用 f.Close() 来关闭。
49. 失败的类型断言在类型断言语句中，断言失败则会返回目标类型的“零值”，断言变量与原来变量混用可能出现异常情况：
// 错误示例func main() &#123;    var data interface&#123;&#125; = &quot;great&quot;    // data 混用    if data, ok := data.(int); ok &#123;        fmt.Println(&quot;[is an int], data: &quot;, data)    &#125; else &#123;        fmt.Println(&quot;[not an int], data: &quot;, data)    // [isn&#x27;t a int], data:  0    &#125;&#125;// 正确示例func main() &#123;    var data interface&#123;&#125; = &quot;great&quot;    if res, ok := data.(int); ok &#123;        fmt.Println(&quot;[is an int], data: &quot;, res)    &#125; else &#123;        fmt.Println(&quot;[not an int], data: &quot;, data)    // [not an int], data:  great    &#125;&#125;

50. 阻塞的 gorutinue 与资源泄露在 2012 年 Google I/O 大会上，Rob Pike 的 Go Concurrency Patterns 演讲讨论 Go 的几种基本并发模式，如 完整代码 中从数据集中获取第一条数据的函数：
func First(query string, replicas []Search) Result &#123;    c := make(chan Result)    replicaSearch := func(i int) &#123; c &lt;- replicas[i](query) &#125;    for i := range replicas &#123;        go replicaSearch(i)    &#125;    return &lt;-c&#125;

在搜索重复时依旧每次都起一个 goroutine 去处理，每个 goroutine 都把它的搜索结果发送到结果 channel 中，channel 中收到的第一条数据会直接返回。
返回完第一条数据后，其他 goroutine 的搜索结果怎么处理？他们自己的协程如何处理？
在 First() 中的结果 channel 是无缓冲的，这意味着只有第一个 goroutine 能返回，由于没有 receiver，其他的 goroutine 会在发送上一直阻塞。如果你大量调用，则可能造成资源泄露。
为避免泄露，你应该确保所有的 goroutine 都能正确退出，有 2 个解决方法：

使用带缓冲的 channel，确保能接收全部 goroutine 的返回结果：

func First(query string, replicas ...Search) Result &#123;    c := make(chan Result,len(replicas))    searchReplica := func(i int) &#123; c &lt;- replicas[i](query) &#125;    for i := range replicas &#123;        go searchReplica(i)    &#125;    return &lt;-c&#125;


使用 select 语句，配合能保存一个缓冲值的 channel default 语句：default 的缓冲 channel 保证了即使结果 channel 收不到数据，也不会阻塞 goroutine

func First(query string, replicas ...Search) Result &#123;    c := make(chan Result,1)    searchReplica := func(i int) &#123;        select &#123;        case c &lt;- replicas[i](query):        default:        &#125;    &#125;    for i := range replicas &#123;        go searchReplica(i)    &#125;    return &lt;-c&#125;


使用特殊的废弃（cancellation） channel 来中断剩余 goroutine 的执行：

func First(query string, replicas ...Search) Result &#123;    c := make(chan Result)    done := make(chan struct&#123;&#125;)    defer close(done)    searchReplica := func(i int) &#123;        select &#123;        case c &lt;- replicas[i](query):        case &lt;- done:        &#125;    &#125;    for i := range replicas &#123;        go searchReplica(i)    &#125;    return &lt;-c&#125;

Rob Pike 为了简化演示，没有提及演讲代码中存在的这些问题。不过对于新手来说，可能会不加思考直接使用。
高级篇：51-5751. 使用指针作为方法的 receiver只要值是可寻址的，就可以在值上直接调用指针方法。即是对一个方法，它的 receiver 是指针就足矣。
但不是所有值都是可寻址的，比如 map 类型的元素、通过 interface 引用的变量：
type data struct &#123;    name string&#125;type printer interface &#123;    print()&#125;func (p *data) print() &#123;    fmt.Println(&quot;name: &quot;, p.name)&#125;func main() &#123;    d1 := data&#123;&quot;one&quot;&#125;    d1.print()    // d1 变量可寻址，可直接调用指针 receiver 的方法    var in printer = data&#123;&quot;two&quot;&#125;    in.print()    // 类型不匹配    m := map[string]data&#123;        &quot;x&quot;: data&#123;&quot;three&quot;&#125;,    &#125;    m[&quot;x&quot;].print()    // m[&quot;x&quot;] 是不可寻址的    // 变动频繁&#125;

cannot use data literal (type data) as type printer in assignment:
data does not implement printer (print method has pointer receiver)
cannot call pointer method on m[“x”]
cannot take the address of m[“x”]
52. 更新 map 字段的值如果 map 一个字段的值是 struct 类型，则无法直接更新该 struct 的单个字段：
// 无法直接更新 struct 的字段值type data struct &#123;    name string&#125;func main() &#123;    m := map[string]data&#123;        &quot;x&quot;: &#123;&quot;Tom&quot;&#125;,    &#125;    m[&quot;x&quot;].name = &quot;Jerry&quot;&#125;

cannot assign to struct field m[“x”].name in map
因为 map 中的元素是不可寻址的。需区分开的是，slice 的元素可寻址：
type data struct &#123;    name string&#125;func main() &#123;    s := []data&#123;&#123;&quot;Tom&quot;&#125;&#125;    s[0].name = &quot;Jerry&quot;    fmt.Println(s)    // [&#123;Jerry&#125;]&#125;

注意：不久前 gccgo 编译器可更新 map struct 元素的字段值，不过很快便修复了，官方认为是 Go1.3 的潜在特性，无需及时实现，依旧在 todo list 中。
更新 map 中 struct 元素的字段值，有 2 个方法：

使用局部变量

// 提取整个 struct 到局部变量中，修改字段值后再整个赋值type data struct &#123;    name string&#125;func main() &#123;    m := map[string]data&#123;        &quot;x&quot;: &#123;&quot;Tom&quot;&#125;,    &#125;    r := m[&quot;x&quot;]    r.name = &quot;Jerry&quot;    m[&quot;x&quot;] = r    fmt.Println(m)    // map[x:&#123;Jerry&#125;]&#125;


使用指向元素的 map 指针

func main() &#123;    m := map[string]*data&#123;        &quot;x&quot;: &#123;&quot;Tom&quot;&#125;,    &#125;    m[&quot;x&quot;].name = &quot;Jerry&quot;    // 直接修改 m[&quot;x&quot;] 中的字段    fmt.Println(m[&quot;x&quot;])    // &amp;&#123;Jerry&#125;&#125;

但是要注意下边这种误用：
func main() &#123;    m := map[string]*data&#123;        &quot;x&quot;: &#123;&quot;Tom&quot;&#125;,    &#125;    m[&quot;z&quot;].name = &quot;what???&quot;    fmt.Println(m[&quot;x&quot;])&#125;

panic: runtime error: invalid memory address or nil pointer dereference
53. nil interface 和 nil interface 值虽然 interface 看起来像指针类型，但它不是。interface 类型的变量只有在类型和值均为 nil 时才为 nil
如果你的 interface 变量的值是跟随其他变量变化的（雾），与 nil 比较相等时小心：
func main() &#123;    var data *byte    var in interface&#123;&#125;    fmt.Println(data, data == nil)    // &lt;nil&gt; true    fmt.Println(in, in == nil)    // &lt;nil&gt; true    in = data    fmt.Println(in, in == nil)    // &lt;nil&gt; false    // data 值为 nil，但 in 值不为 nil&#125;

如果你的函数返回值类型是 interface，更要小心这个坑：
// 错误示例func main() &#123;    doIt := func(arg int) interface&#123;&#125; &#123;        var result *struct&#123;&#125; = nil        if arg &gt; 0 &#123;            result = &amp;struct&#123;&#125;&#123;&#125;        &#125;        return result    &#125;    if res := doIt(-1); res != nil &#123;        fmt.Println(&quot;Good result: &quot;, res)    // Good result:  &lt;nil&gt;        fmt.Printf(&quot;%T\n&quot;, res)            // *struct &#123;&#125;    // res 不是 nil，它的值为 nil        fmt.Printf(&quot;%v\n&quot;, res)            // &lt;nil&gt;    &#125;&#125;// 正确示例func main() &#123;    doIt := func(arg int) interface&#123;&#125; &#123;        var result *struct&#123;&#125; = nil        if arg &gt; 0 &#123;            result = &amp;struct&#123;&#125;&#123;&#125;        &#125; else &#123;            return nil    // 明确指明返回 nil        &#125;        return result    &#125;    if res := doIt(-1); res != nil &#123;        fmt.Println(&quot;Good result: &quot;, res)    &#125; else &#123;        fmt.Println(&quot;Bad result: &quot;, res)    // Bad result:  &lt;nil&gt;    &#125;&#125;

54. 堆栈变量你并不总是清楚你的变量是分配到了堆还是栈。
在 C++ 中使用 new 创建的变量总是分配到堆内存上的，但在 Go 中即使使用 new()、make() 来创建变量，变量为内存分配位置依旧归 Go 编译器管。
Go 编译器会根据变量的大小及其 “escape analysis” 的结果来决定变量的存储位置，故能准确返回本地变量的地址，这在 C/C++ 中是不行的。
在 go build 或 go run 时，加入 -m 参数，能准确分析程序的变量分配位置：

55. GOMAXPROCS、Concurrency（并发）and Parallelism（并行）Go 1.4 及以下版本，程序只会使用 1 个执行上下文 / OS 线程，即任何时间都最多只有 1 个 goroutine 在执行。
Go 1.5 版本将可执行上下文的数量设置为 runtime.NumCPU() 返回的逻辑 CPU 核心数，这个数与系统实际总的 CPU 逻辑核心数是否一致，取决于你的 CPU 分配给程序的核心数，可以使用 GOMAXPROCS 环境变量或者动态的使用 runtime.GOMAXPROCS() 来调整。
误区：GOMAXPROCS 表示执行 goroutine 的 CPU 核心数，参考文档
GOMAXPROCS 的值是可以超过 CPU 的实际数量的，在 1.5 中最大为 256
func main() &#123;    fmt.Println(runtime.GOMAXPROCS(-1))    // 4    fmt.Println(runtime.NumCPU())    // 4    runtime.GOMAXPROCS(20)    fmt.Println(runtime.GOMAXPROCS(-1))    // 20    runtime.GOMAXPROCS(300)    fmt.Println(runtime.GOMAXPROCS(-1))    // Go 1.9.2 // 300&#125;

56. 读写操作的重新排序Go 可能会重排一些操作的执行顺序，可以保证在一个 goroutine 中操作是顺序执行的，但不保证多 goroutine 的执行顺序：
var _ = runtime.GOMAXPROCS(3)var a, b intfunc u1() &#123;    a = 1    b = 2&#125;func u2() &#123;    a = 3    b = 4&#125;func p() &#123;    println(a)    println(b)&#125;func main() &#123;    go u1()    // 多个 goroutine 的执行顺序不定    go u2()    go p()    time.Sleep(1 * time.Second)&#125;

运行效果：

如果你想保持多 goroutine 像代码中的那样顺序执行，可以使用 channel 或 sync 包中的锁机制等。
57. 优先调度你的程序可能出现一个 goroutine 在运行时阻止了其他 goroutine 的运行，比如程序中有一个不让调度器运行的 for 循环：
func main() &#123;    done := false    go func() &#123;        done = true    &#125;()    for !done &#123;    &#125;    println(&quot;done !&quot;)&#125;

for 的循环体不必为空，但如果代码不会触发调度器执行，将出现问题。
调度器会在 GC、Go 声明、阻塞 channel、阻塞系统调用和锁操作后再执行，也会在非内联函数调用时执行：
func main() &#123;    done := false    go func() &#123;        done = true    &#125;()    for !done &#123;        println(&quot;not done !&quot;)    // 并不内联执行    &#125;    println(&quot;done !&quot;)&#125;

可以添加 -m 参数来分析 for 代码块中调用的内联函数：

你也可以使用 runtime 包中的 Gosched() 来 手动启动调度器：
func main() &#123;    done := false    go func() &#123;        done = true    &#125;()    for !done &#123;        runtime.Gosched()    &#125;    println(&quot;done !&quot;)&#125;



运行效果：

接上篇，上次提到了排查是因为服务器的磁盘不够导致服务器没有写入的空间，进一步导致服务器宕机，下面是我清理磁盘日志的操作。 清理日志文件(*.log文件)我们的Java的日志文件是根据日期分开成不同的log，所以我写了一个shell脚本用来每天定时清理三天之前的所有日志文件。 清理的Linux命令如下： find log文件的文件路径 -mtime +3 -name &quot;*.log&quot; -exec rm -rf &#123;&#125; \;
shell脚本命令如下： #!/bin/bash# 指定日志目录路径log_dir=&quot;*******/***/***&quot;# 计算三天前的日期three_days_ago=$(date -d &quot;3 days ago&quot; +%Y%m%d)# 删除三天前的日志文件find &quot;$log_dir&quot; -mtime +3 -name &quot;*.log&quot; -exec rm -rf &#123;&#125; \;echo &quot;已删除 $log_dir 目录下 $three_days_ago 之前的日志文件。&quot;
保存为一个shell脚本文件之后，赋予此文件执行权限： chmod +x cleanup_logs.sh
然后写一个定时任务，让这个shell脚本文件每天早上八点执行一次 # 打开cron编辑器crontab -e
然后在编辑器中添加以下行，以在每天的固定时间执行脚本（假设你希望在每天的凌晨8点执行）： 0 8 * * * /path/to/cleanup_logs.sh#文件路径：/path/to/cleanup_logs.sh
清理MySQL中request_log表的文件：由于这个表已经非常大了、估计多少有个几千万条记录了、通过delete from tableName肯定是不现实了，那么因为需要MySQL会先查数据然后删相关数据，所以我想到了分段删除的思想，也就是分批次来删除半年前的数据，那么这时候就有一个问题了，难不成手动删？显然不现实，于是我想到了MySQL中的定时器PROCEDURE，先定义个PROCEDURE函数，具体函数实现如下： DELIMITER //CREATE PROCEDURE DeleteOldRecords()BEGIN DECLARE batch_size INT DEFAULT 10000; -- 每批次删除的记录数 DECLARE total_records INT; DECLARE deleted_records INT; SET total_records = (SELECT COUNT(*) FROM tableName WHERE create_time &lt;= DATE_SUB(NOW(), INTERVAL 6 MONTH)); WHILE total_records &gt; 0 DO DELETE FROM tableName WHERE create_time &lt;= DATE_SUB(NOW(), INTERVAL 6 MONTH) LIMIT batch_size; SET deleted_records = ROW_COUNT(); SET total_records = total_records - deleted_records; END WHILE;END //DELIMITER ;#create_time代表某条记录的创建时间字段#tableName代表你要执行函数的表名
最后执行CALL DeleteOldRecords();的sql语句使以上函数开始删除相关记录 当然还需要等执行完此函数之后，删除此函数，sql命令如下： DROP PROCEDURE IF EXISTS DeleteOldRecords;
